  {q:"El área de un triángulo de base 8 cm y altura 5 cm es:",o:["40 cm²","13 cm²","20 cm²","16 cm²"],a:2,tip:"Área triángulo = (base × altura) ÷ 2 = (8 × 5) ÷ 2 = 20 cm²."},
  {q:"¿Qué tipo de ángulo tiene menos de 90°?",o:["Obtuso","Recto","Agudo","Llano"],a:2,tip:"El ángulo agudo mide menos de 90°. Piensa: 'agudo = pequeño y afilado'."}
