//   QD_MEDIO — Nivel Medio (25 preguntas por biome)
// ═══════════════════════════════════════════
const QD_MEDIO={
ingles:[
  // MISIÓN 1 — Past tense verbs, comparatives
  {q:"What is the PAST TENSE of 'go'?",o:["goed","went","gone","going"],a:1,tip:"'Go' es irregular en pasado: went. No se le agrega -ed.",img:"past_go"},
  {q:"She ___ to school yesterday. (past tense of 'walk')",o:["walks","walked","walking","walk"],a:1,tip:"Verbos regulares en pasado llevan -ed: walked.",img:"past_walk"},
  {q:"Which is BIGGER: an elephant or a mouse?",o:["The mouse","The elephant","They are the same","Neither"],a:1,tip:"Bigger = más grande. Un elefante es más grande que un ratón.",img:"elephant_mouse"},
  {q:"He ___ his homework last night. (past tense of 'do')",o:["do","does","did","done"],a:2,tip:"'Do' es irregular: did en pasado simple.",img:"past_do"},
  {q:"My house is SMALLER than the school. 'Smaller' means:",o:["más grande","más pequeña","igual","más rápida"],a:1,tip:"Smaller = más pequeña/pequeño.",img:"smaller"},
  // MISIÓN 2 — Adverbs of frequency, prepositions
  {q:"I ___ wake up at 7 AM. (always/sometimes/never)",o:["always","never","yesterday","tomorrow"],a:0,tip:"'Always' = siempre. Significa que hago algo todos los días.",img:"always"},
  {q:"The cat is ___ the box. It is inside.",o:["next to","under","in","behind"],a:2,tip:"'In' = dentro de. El gato está dentro de la caja.",img:"cat_in_box"},
  {q:"The ball is ___ the table and the chair. It is between them.",o:["under","next to","between","on"],a:2,tip:"'Between' = entre dos cosas.",img:"between"},
  {q:"She ___ eats vegetables. She doesn't like them.",o:["always","sometimes","never","often"],a:2,tip:"'Never' = nunca. Ella no come vegetales.",img:"never_veg"},
  {q:"The park is ___ my house. You can walk there.",o:["behind","next to","under","between"],a:1,tip:"'Next to' = al lado de / cerca de.",img:"next_to"},
  // MISIÓN 3 — Simple past questions, time expressions
  {q:"___ you go to the park yesterday?",o:["Do","Did","Does","Are"],a:1,tip:"En preguntas de pasado simple se usa DID: Did you go...?",img:"did_you"},
  {q:"We played soccer ___ week.",o:["this","next","in","a"],a:0,tip:"'This week' = esta semana. 'Last week' = la semana pasada.",img:"this_week"},
  {q:"___ she watch TV last night?",o:["Do","Did","Does","Is"],a:1,tip:"'Did' se usa para preguntas en pasado simple con cualquier persona.",img:"did_she"},
  {q:"I visited my grandma ___ Saturday.",o:["in","on","at","next"],a:1,tip:"Se usa 'on' con días de la semana: on Monday, on Saturday.",img:"on_saturday"},
  {q:"Did they ___ to the beach? Yes, they did.",o:["went","go","goes","going"],a:1,tip:"Después de 'did' el verbo regresa a su forma base (infinitivo sin to).",img:"did_base"},
  // MISIÓN 4 — Short paragraph comprehension
  {q:"📖 'Last weekend, Maria went to the zoo. She saw lions, monkeys and elephants. Her favorite animal was the elephant because it was very big.' What did Maria see at the zoo?",o:["Dogs and cats","Lions, monkeys and elephants","Only birds","Fish"],a:1,tip:"El texto dice que vio leones (lions), monos (monkeys) y elefantes (elephants).",img:"zoo_read"},
  {q:"📖 'Last weekend, Maria went to the zoo. She saw lions, monkeys and elephants. Her favorite animal was the elephant because it was very big.' Why was the elephant her favorite?",o:["Because it was small","Because it was very big","Because it was funny","Because it was fast"],a:1,tip:"El texto dice 'because it was very big' = porque era muy grande.",img:"zoo_fav"},
  {q:"📖 'Tom gets up at 6 AM, eats breakfast at 7, and goes to school at 8. He comes home at 3 PM.' What time does Tom go to school?",o:["At 6 AM","At 7 AM","At 8 AM","At 3 PM"],a:2,tip:"El texto dice 'goes to school at 8'.",img:"tom_schedule"},
  {q:"📖 'Tom gets up at 6 AM, eats breakfast at 7, and goes to school at 8. He comes home at 3 PM.' What does Tom do at 7 AM?",o:["He gets up","He eats breakfast","He goes to school","He comes home"],a:1,tip:"A las 7 AM, Tom come el desayuno (eats breakfast).",img:"tom_breakfast"},
  {q:"📖 'Lucy likes to read books. She reads every day after school. Her favorite book is about animals.' When does Lucy read?",o:["Before school","During school","After school","On weekends"],a:2,tip:"El texto dice 'after school' = después de la escuela.",img:"lucy_reads"},
  // MODO EXTRA — Mixed review
  {q:"Choose the CORRECT sentence:",o:["She goed to the store.","She went to the store.","She gone to the store.","She go to the store."],a:1,tip:"'Go' en pasado es 'went'. She went = Ella fue.",img:"correct_past"},
  {q:"'I played soccer ___.' Which word fills the blank? (yesterday / tomorrow / now)",o:["tomorrow","now","yesterday","every day"],a:2,tip:"'Played' es pasado, entonces usamos 'yesterday' = ayer.",img:"yesterday"},
  {q:"The dog is ___ the door. It cannot go inside.",o:["in","on","outside","under"],a:2,tip:"El perro está AFUERA de la puerta = outside.",img:"dog_outside"},
  {q:"Which sentence is in the PRESENT?",o:["She played yesterday.","She plays every day.","She will play tomorrow.","She went to school."],a:1,tip:"'Plays every day' = juega todos los días. Es presente (present tense).",img:"present_tense"},
  {q:"What is the opposite of 'big'?",o:["tall","small","fast","happy"],a:1,tip:"Big = grande. Su opuesto es small = pequeño.",img:"opposite_big"}
],
lenguaje:[
  // MISIÓN 1 — Propósito del texto
  {q:"Un cuento que narra la vida de un personaje se llama texto:",o:["informativo","narrativo","instructivo","publicitario"],a:1,tip:"Los textos narrativos cuentan historias con personajes y secuencias de eventos.",img:"narrativo_tipo"},
  {q:"Un texto que explica paso a paso cómo hacer una receta es:",o:["narrativo","poético","instructivo","descriptivo"],a:2,tip:"Los textos instructivos dan instrucciones ordenadas para hacer algo.",img:"instructivo_tipo"},
  {q:"¿Cuál es el propósito de un texto argumentativo?",o:["Contar una historia bonita","Dar información objetiva","Convencer al lector de una idea","Explicar cómo hacer algo"],a:2,tip:"El texto argumentativo defiende una opinión y quiere convencer al lector.",img:"argumentativo"},
  {q:"Una carta que envía una tienda para ofrecer productos es un texto:",o:["narrativo","instructivo","epistolar / publicitario","poético"],a:2,tip:"Las cartas comerciales son textos publicitarios que quieren vender algo.",img:"carta_tienda"},
  {q:"¿Qué tipo de texto es un poema con rima y ritmo?",o:["Informativo","Poético","Instructivo","Epistolar"],a:1,tip:"El texto poético usa rima, ritmo, versos y lenguaje creativo.",img:"poema_tipo"},
  // MISIÓN 2 — Sinónimos y antónimos
  {q:"¿Cuál es un SINÓNIMO de 'grande'?",o:["pequeño","enorme","rápido","triste"],a:1,tip:"Sinónimo = palabra con significado similar. Grande ≈ enorme.",img:"grande_sin"},
  {q:"¿Cuál es un ANTÓNIMO de 'feliz'?",o:["contento","alegre","triste","bonito"],a:2,tip:"Antónimo = palabra con significado opuesto. Feliz ↔ triste.",img:"feliz_anton"},
  {q:"¿Cuál es sinónimo de 'caminar'?",o:["correr","andar","saltar","dormir"],a:1,tip:"Caminar y andar significan lo mismo = sinónimos.",img:"caminar_sin"},
  {q:"'Rápido' es antónimo de:",o:["veloz","lento","fuerte","alto"],a:1,tip:"Rápido ↔ lento. Son opuestos en velocidad.",img:"rapido_anton"},
  {q:"¿Cuál es sinónimo de 'hermoso'?",o:["feo","bonito","grande","oscuro"],a:1,tip:"Hermoso ≈ bonito. Ambos describen algo bello.",img:"hermoso_sin"},
  // MISIÓN 3 — Poesía
  {q:"¿Qué es la RIMA en un poema?",o:["El tamaño de las letras","La repetición de sonidos al final de los versos","La cantidad de estrofas","El título del poema"],a:1,tip:"La rima es cuando los versos terminan con sonidos similares.",img:"rima"},
  {q:"Un VERSO es:",o:["Un libro completo","Una línea de un poema","Una carta","Un dibujo"],a:1,tip:"Un verso es cada línea de un poema.",img:"verso"},
  {q:"¿Qué es una ESTROFA?",o:["Un verso solo","Un grupo de versos","El título del poema","Un dibujo"],a:1,tip:"Una estrofa es un conjunto de versos que forman un párrafo del poema.",img:"estrofa"},
  {q:"¿Cuántas sílabas tiene la palabra 'mariposa'?",o:["2","3","4","5"],a:2,tip:"ma-ri-po-sa = 4 sílabas.",img:"mariposa_sil"},
  {q:"Las palabras que tienen el mismo sonido final en un poema:",o:["no tienen relación","están en prosa","riman entre sí","son sinónimas"],a:2,tip:"Cuando los versos terminan con sonido similar, se dice que riman.",img:"rima_sonido"},
  // MISIÓN 4 — Ortografía y puntuación
  {q:"¿En cuál oración se usa MAYÚSCULA correctamente?",o:["mi perro se llama rex","Mi perro se llama Rex","mi Perro se llama rex","mi perro Se llama rex"],a:1,tip:"Las mayúsculas van al inicio de la oración y en nombres propios (Rex).",img:"mayuscula"},
  {q:"¿Cuál es el signo de puntuación que se usa al final de una pregunta?",o:[".","?",",","!"],a:1,tip:"Las preguntas terminan con signo de interrogación (?).",img:"interrogacion"},
  {q:"La COMA (,) se usa para:",o:["terminar una oración","separar elementos en una lista","iniciar una pregunta","dar énfasis"],a:1,tip:"La coma separa elementos en una enumeración: perros, gatos, pájaros.",img:"coma_uso"},
  {q:"¿Cuál oración tiene los signos de exclamación correctos?",o:["¡Qué bonito día","¡Qué bonito día!","Qué bonito día¡","Qué¡ bonito día!"],a:1,tip:"Los signos de exclamación van al inicio y al final: ¡...!",img:"exclamacion"},
  {q:"¿Dónde va el punto final (.)?",o:["Al inicio de la oración","Al final de la oración","En medio de la oración","No se usa más"],a:1,tip:"El punto (.) se coloca al final de una oración declarativa.",img:"punto_final"},
  // MODO EXTRA — Mixed review
  {q:"Un texto que describe un lugar usando los 5 sentidos es:",o:["narrativo","descriptivo","instructivo","argumentativo"],a:1,tip:"El texto descriptivo usa detalles sensoriales para pintar una imagen mental.",img:"descriptivo_5sentidos"},
  {q:"El conector 'además' sirve para:",o:["contrastar ideas","agregar más información","iniciar una pregunta","terminar un texto"],a:1,tip:"'Además' = también / agregando más información.",img:"ademas"},
  {q:"¿Cuál es el antónimo de 'oscuro'?",o:["claro","grande","triste","lento"],a:0,tip:"Oscuro ↔ claro. Son opuestos.",img:"oscuro_anton"},
  {q:"Un texto que cuenta la vida de una persona real es una:",o:["ficción","biografía","fábula","receta"],a:1,tip:"La biografía narra la vida real de una persona.",img:"biografia"},
  {q:"¿Qué tipo de texto es una noticia?",o:["Narrativo","Informativo","Poético","Instructivo"],a:1,tip:"Las noticias informan sobre hechos reales de interés público.",img:"noticia_tipo"}
],
matematicas:[
  // MISIÓN 1 — Problemas de 2 pasos
  {q:"Ana compra 3 cuadernos a $2.000 cada uno. Paga con $10.000. ¿Cuánto recibe de vuelto?",o:["$4.000","$6.000","$3.000","$5.000"],a:0,tip:"3×$2.000=$6.000. Vuelto: $10.000-$6.000=$4.000.",img:"buy_change"},
  {q:"Pedro tiene 15 caramelos. Da 5 a su hermano y compra 3 más. ¿Cuántos tiene ahora?",o:["12","13","8","17"],a:1,tip:"15-5=10, 10+3=13 caramelos.",img:"candies_2step"},
  {q:"Una caja tiene 24 manzanas. Se reparten en partes iguales entre 4 niños. ¿Cuántas le tocan a cada uno?",o:["6","8","5","7"],a:0,tip:"24÷4=6 manzanas a cada niño.",img:"divide_apples"},
  {q:"María leyó 12 páginas el lunes y el doble el martes. ¿Cuántas páginas leyó en total?",o:["24","36","18","48"],a:1,tip:"Martes: 12×2=24. Total: 12+24=36 páginas.",img:"pages_read"},
  {q:"Un bus tiene 30 asientos. En la primera parada suben 18 personas, en la segunda bajan 5. ¿Cuántos pasajeros van ahora?",o:["13","18","23","25"],a:0,tip:"18-5=13 pasajeros viajando.",img:"bus_passengers"},
  // MISIÓN 2 — Perímetro
  {q:"Un rectángulo mide 8 cm de largo y 5 cm de ancho. ¿Cuál es su perímetro?",o:["13 cm","26 cm","40 cm","20 cm"],a:1,tip:"Perímetro = 2×(largo+ancho) = 2×(8+5) = 2×13 = 26 cm.",img:"rect_perimeter"},
  {q:"Un triángulo tiene lados de 4 cm, 5 cm y 6 cm. ¿Cuál es su perímetro?",o:["15 cm","14 cm","16 cm","13 cm"],a:0,tip:"Perímetro = suma de todos los lados: 4+5+6 = 15 cm.",img:"tri_perimeter"},
  {q:"Un cuadrado tiene 7 cm de lado. ¿Cuál es su perímetro?",o:["14 cm","21 cm","28 cm","49 cm"],a:2,tip:"Perímetro del cuadrado = 4×lado = 4×7 = 28 cm.",img:"sq_perimeter"},
  {q:"Laura camina alrededor de un parque rectangular de 10 m por 6 m. ¿Cuántos metros camina?",o:["16 m","60 m","32 m","20 m"],a:2,tip:"Camina el perímetro: 2×(10+6) = 32 m.",img:"park_walk"},
  {q:"Un triángulo equilátero tiene 9 cm por lado. ¿Cuál es su perímetro?",o:["18 cm","27 cm","36 cm","81 cm"],a:1,tip:"Equilátero = 3 lados iguales: 9+9+9 = 27 cm.",img:"eq_tri_perimeter"},
  // MISIÓN 3 — Fracciones equivalentes
  {q:"¿Cuál fracción es EQUIVALENTE a 2/4?",o:["1/2","3/4","2/3","1/3"],a:0,tip:"2/4 = 1/2 (divide numerador y denominador por 2).",img:"equiv_frac"},
  {q:"¿Cuál fracción es equivalente a 3/6?",o:["1/2","2/3","1/3","3/4"],a:0,tip:"3/6 = 1/2 (divide por 3: 3÷3=1, 6÷3=2).",img:"equiv_36"},
  {q:"¿Cuál es mayor: 1/2 o 1/4?",o:["1/2","1/4","Son iguales","No se puede saber"],a:0,tip:"Con mismo denominador, mayor numerador = mayor fracción. 1/2 > 1/4.",img:"compare_half"},
  {q:"¿Cuánto es 1/2 de 20?",o:["5","8","10","15"],a:2,tip:"La mitad de 20 = 20÷2 = 10.",img:"half_of_20"},
  {q:"¿Cuánto es 1/4 de 16?",o:["2","4","8","6"],a:1,tip:"Un cuarto de 16 = 16÷4 = 4.",img:"quarter_of_16"},
  // MISIÓN 4 — Tiempo
  {q:"Si el reloj marca las 3:00, ¿qué hora será en 2 horas más?",o:["5:00","4:00","1:00","6:00"],a:0,tip:"3:00 + 2 horas = 5:00.",img:"clock_add"},
  {q:"La película empezó a las 4:30 y terminó a las 6:00. ¿Cuánto duró?",o:["1 hora","1 hora y media","2 horas","2 horas y media"],a:1,tip:"De 4:30 a 6:00 = 1 hora y 30 minutos.",img:"movie_time"},
  {q:"¿Qué hora marca el reloj si la manecilla grande está en el 6 y la pequeña en el 12?",o:["6:00","12:30","12:00","3:00"],a:0,tip:"Manecilla grande en 6 = 30 minutos. Pequeña en 12 = 12 horas. Son las 12:30.",img:"clock_read"},
  {q:"Tomás sale de casa a las 7:15 AM y llega a la escuela a las 7:45 AM. ¿Cuánto tarda?",o:["15 minutos","30 minutos","45 minutos","20 minutos"],a:1,tip:"7:45 - 7:15 = 30 minutos de camino.",img:"school_time"},
  {q:"¿Cuántos minutos hay en media hora?",o:["15","60","30","45"],a:2,tip:"Una hora = 60 minutos. Media hora = 30 minutos.",img:"half_hour"},
  // MODO EXTRA — Mixed con pictograma
  {q:"📊 Usando el pictograma de aves (1 dibujo = 3 aves), si el sábado Luisa observó 6 dibujos, ¿cuántas aves vio?",o:["6","18","9","3"],a:1,tip:"6 dibujos × 3 = 18 aves.",img:"bird_sat",birdRef:true},
  {q:"📊 Si el promedio de aves por día es 6,6 (33÷5), ¿cuántas aves faltarían para llegar a 40 en la semana?",o:["5","7","8","10"],a:1,tip:"40 - 33 = 7 aves más.",img:"bird_average",birdRef:true},
  {q:"Un rectángulo tiene perímetro 20 cm. Si el largo es 6 cm, ¿cuánto mide el ancho?",o:["5 cm","4 cm","6 cm","8 cm"],a:1,tip:"2×(6+ancho)=20 → 6+ancho=10 → ancho=4 cm.",img:"perimeter_sides"},
  {q:"¿Cuántas horas y minutos hay en 90 minutos?",o:["1 hora 20 min","1 hora 30 min","2 horas","1 hora 40 min"],a:1,tip:"60 minutos = 1 hora. 90-60=30. Son 1 hora y 30 minutos.",img:"convert_time"},
  {q:"📊 ¿En qué día observó Luisa exactamente la mitad de las aves que observó el jueves (12 aves)?",o:["Lunes (9 aves)","Martes (6 aves)","Miércoles (3 aves)","Viernes (3 aves)"],a:1,tip:"La mitad de 12 = 6. Martes tiene 6 aves (2 dibujos × 3).",img:"bird_half",birdRef:true}
],
ciencias:[
  // MISIÓN 1 — Ciclos de vida
  {q:"¿En qué orden se transforma una mariposa?",o:["Huevo → oruga → crisálida → mariposa","Mariposa → oruga → huevo","Oruga → huevo → crisálida","Crisálida → huevo → mariposa"],a:0,tip:"El ciclo es: huevo → oruga → crisálida → mariposa adulta.",img:"butterfly_cycle"},
  {q:"¿Cómo nace una rana?",o:["De un huevo que pone la mamá en el agua","De una semilla","De una crisálida","De un cachorro"],a:0,tip:"Las ranas ponen huevos en el agua. De allí nacen los renacuajos.",img:"frog_birth"},
  {q:"¿Cuál es la primera etapa del ciclo de vida de una planta con flor?",o:["La semilla","La flor","La raíz","El fruto"],a:0,tip:"Las plantas con flor empiezan como semillas que germinan.",img:"plant_seed"},
  {q:"El renacuajo se transforma en rana. ¿Cómo se llama este proceso?",o:["Fotosíntesis","Metamorfosis","Evaporación","Germinación"],a:1,tip:"La metamorfosis es el cambio de forma: renacuajo → rana.",img:"metamorfosis"},
  {q:"¿Qué necesita una semilla para germinar?",o:["Sol, agua y tierra adecuada","Solo luz","Solo agua","Solo aire"],a:0,tip:"Las semillas necesitan agua, temperatura adecuada y oxígeno para germinar.",img:"seed_grow"},
  // MISIÓN 2 — Energía
  {q:"La energía CINÉTICA es la energía del:",o:["reposo","movimiento","calor","luz"],a:1,tip:"Cinética = movimiento. Un carro en movimiento tiene energía cinética.",img:"kinetic"},
  {q:"La energía POTENCIAL es la energía que tiene un objeto por:",o:["su movimiento","su velocidad","su posición o altura","su color"],a:2,tip:"Un objeto alto tiene energía potencial por su posición (gravedad).",img:"potential"},
  {q:"¿Qué tipo de energía produce una pilas o batería?",o:["Energía solar","Energía eléctrica","Energía eólica","Energía nuclear"],a:1,tip:"Las pilas almacenan y producen energía eléctrica.",img:"battery"},
  {q:"La energía que llega del Sol se llama energía:",o:["eléctrica","nuclear","solar","eólica"],a:2,tip:"Solar = del Sol. El Sol nos da luz y calor.",img:"solar_energy"},
  {q:"¿Qué aparato transforma energía eléctrica en luz?",o:["Un estufa","Un televisor","Una nevera","Un ventilador"],a:1,tip:"El televisor usa electricidad para producir imagen y luz.",img:"electric_light"},
  // MISIÓN 3 — Mezclas
  {q:"Una mezcla HOMOGÉNEA es aquella donde:",o:["se ven los componentes","no se distinguen los componentes","solo tiene un componente","es sólida siempre"],a:1,tip:"Homogénea = los componentes no se ven por separado (ej: jugo de naranja).",img:"homogenea"},
  {q:"¿Cuál es una mezcla HETEROGÉNEA?",o:["Agua con sal disuelta","Jugo de limón","Ensalada con tomate y lechuga","Café con azúcar"],a:2,tip:"En la ensalada se ven los ingredientes por separado = heterogénea.",img:"heterogenea"},
  {q:"Cuando mezclas agua y arena y luego la dejas reposar, la arena se va al fondo. Esto se llama:",o:["evaporación","decantación","fusión","sublimación"],a:1,tip:"La decantación separa componentes por su peso (arena es más pesada).",img:"decantacion"},
  {q:"¿Cuál es un ejemplo de mezcla homogénea?",o:["Cereal con leche","Agua con aceite","Limonada","Ensalada"],a:2,tip:"La limonada parece un líquido uniforme = mezcla homogénea.",img:"limonada"},
  {q:"Para separar el agua de la sal en agua de mar, se puede usar:",o:["un imán","evaporación","un colador","decantación"],a:1,tip:"Al evaporar el agua, la sal queda como sólido = evaporación.",img:"evaporacion"},
  // MISIÓN 4 — Cuerpo humano
  {q:"¿Por dónde entra el oxígeno a nuestro cuerpo?",o:["Por la boca y la nariz","Por los oídos","Por la piel","Por los ojos"],a:0,tip:"Respiramos por la nariz y la boca. El oxígeno llega a los pulmones.",img:"breathe_in"},
  {q:"¿Cuál es la función principal del sistema digestivo?",o:["Mover el cuerpo","Transformar los alimentos en nutrientes","Pensar","Ver"],a:1,tip:"El sistema digestivo descompone la comida para que el cuerpo la use.",img:"digestive"},
  {q:"El corazón es parte del sistema:",o:["digestivo","respiratorio","circulatorio","óseo"],a:2,tip:"El corazón bombea sangre por todo el cuerpo = sistema circulatorio.",img:"heart_system"},
  {q:"¿Cuál es el órgano principal del sistema respiratorio?",o:["El estómago","El cerebro","Los pulmones","El corazón"],a:2,tip:"Los pulmones son los órganos donde se realiza el intercambio de gases.",img:"lungs"},
  {q:"Los huesos forman parte del sistema:",o:["muscular","digestivo","nervioso","óseo"],a:3,tip:"Los huesos = sistema óseo. Dan forma y protección al cuerpo.",img:"skeletal"},
  // MODO EXTRA — Mixed review
  {q:"¿Qué proceso usan las plantas para hacer su alimento usando la luz del sol?",o:["Respiración","Fotosíntesis","Digestión","Evaporación"],a:1,tip:"Las plantas usan luz solar, agua y CO₂ para hacer alimento = fotosíntesis.",img:"photosynthesis"},
  {q:"Un imán tiene dos polos:",o:["positivo y negativo","norte y sur","grande y pequeño","caliente y frío"],a:1,tip:"Los polos del imán se llaman norte (N) y sur (S).",img:"magnet_poles"},
  {q:"¿Qué pasa si acercas dos imanes por el polo norte?",o:["Se atraen","Se repelen","No pasa nada","Se funden"],a:1,tip:"Polos iguales se repelen. Polos diferentes se atraen.",img:"poles_repel"},
  {q:"La fuerza de gravedad nos mantiene:",o:["flotando","pegados al suelo","volando","corriendo rápido"],a:1,tip:"La gravedad es la fuerza que nos atrae hacia la Tierra.",img:"gravity"},
  {q:"¿Cuál es la fuente principal de energía de la Tierra?",o:["La Luna","El viento","El Sol","Las estrellas"],a:2,tip:"El Sol es la principal fuente de calor y luz de la Tierra.",img:"sun_source"}
],
sociales:[
  // MISIÓN 1 — Regiones de Colombia
  {q:"La Región Andina de Colombia se caracteriza por tener:",o:["Playas y mar","Montañas y cordilleras","Selvas tropicales","Desiertos"],a:1,tip:"La Región Andina tiene las 3 cordilleras de los Andes.",img:"andina"},
  {q:"¿En qué región de Colombia están las ciudades de Cartagena y Barranquilla?",o:["Región Andina","Región Caribe","Región Pacífica","Región Orinoquía"],a:1,tip:"Cartagena y Barranquilla están en la Región Caribe, cerca del mar Caribe.",img:"caribe"},
  {q:"La selva amazónica en Colombia pertenece a la región:",o:["Andina","Caribe","Amazónica","Insular"],a:2,tip:"La selva amazónica está en la Región Amazónica (sur del país).",img:"amazonica"},
  {q:"¿Cuántas regiones naturales tiene Colombia?",o:["4","5","6","8"],a:2,tip:"Colombia tiene 6 regiones: Andina, Caribe, Pacífica, Orinoquía, Amazónica e Insular.",img:"6_regiones"},
  {q:"La Región Pacífica de Colombia bañada por el océano:",o:["Atlántico","Índico","Pacífico","Ártico"],a:2,tip:"La Región Pacífica está bañada por el Océano Pacífico.",img:"pacifico"},
  // MISIÓN 2 — Economía
  {q:"La AGRICULTURA es una actividad económica que consiste en:",o:["fabricar carros","cultivar la tierra","vender ropa","construir casas"],a:1,tip:"La agricultura es sembrar y cultivar alimentos en la tierra.",img:"agricultura"},
  {q:"¿Cuál es una actividad MINERA en Colombia?",o:["Pescar en ríos","Extraer carbón y esmeraldas","Cultivar café","Tejer telas"],a:1,tip:"Colombia extrae minerales como carbón, esmeraldas y oro = minería.",img:"mineria_col"},
  {q:"¿Qué es el TURISMO como actividad económica?",o:["Fabricar alimentos","Viajar por placer y conocer lugares","Construir puentes","Enseñar en escuelas"],a:1,tip:"El turismo es viajar para conocer lugares y generar ingresos.",img:"turismo"},
  {q:"El café es uno de los principales productos de exportación de Colombia. ¿Qué actividad representa?",o:["Minería","Agricultura","Industria","Turismo"],a:1,tip:"Cultivar café es una actividad agrícola.",img:"cafe_colombia"},
  {q:"Cuando alguien compra algo en una tienda, está participando como:",o:["productor","vendedor","consumidor","transportador"],a:2,tip:"El consumidor es quien compra y usa los productos o servicios.",img:"consumidor"},
  // MISIÓN 3 — Medios de comunicación
  {q:"¿Cuál medio de comunicación usa imágenes y texto en papel?",o:["La radio","El periódico","La televisión","Internet"],a:1,tip:"El periódico = newspaper. Usa fotos y texto impreso en papel.",img:"periodico"},
  {q:"¿Cuál medio de comunicación permite escuchar noticias sin ver imágenes?",o:["La televisión","El cine","La radio","El periódico"],a:2,tip:"La radio transmite sonidos. Se escucha sin ver.",img:"radio"},
  {q:"Internet permite:",o:["Solo ver videos","Comunicarse, buscar información y aprender","Solo enviar mensajes","Solo escuchar música"],a:1,tip:"Internet sirve para muchas cosas: comunicarse, aprender, investigar, etc.",img:"internet"},
  {q:"¿Qué medio de comunicación muestra noticias con video y sonido?",o:["La radio","El periódico","La televisión","Una carta"],a:2,tip:"La televisión combina video y sonido para mostrar noticias.",img:"television"},
  {q:"Una CARTA es un medio de comunicación que:",o:["se envía por televisión","es un mensaje escrito de persona a persona","se escucha en la radio","es una foto"],a:1,tip:"Una carta es un mensaje escrito que una persona envía a otra.",img:"carta_medio"},
  // MISIÓN 4 — Derechos de los niños (detalle)
  {q:"Según los Derechos de los Niños, todos tienen derecho a:",o:["trabajar desde pequeños","la educación","no tener familia","comprar lo que quieran"],a:1,tip:"El derecho a la educación está en la Convención sobre los Derechos del Niño.",img:"derecho_edu"},
  {q:"El derecho a la PROTECCIÓN significa que los niños deben estar:",o:["solos en casa","seguros y cuidados","trabajando","sin jugar"],a:1,tip:"Protección = estar seguros, cuidados y libres de daño.",img:"proteccion"},
  {q:"¿Cuál de estos es un DEBER de los niños?",o:["No ir a la escuela","Respetar a los demás","Comprar todo lo que quieren","No obedecer reglas"],a:1,tip:"Los deberes incluyen respetar a los demás y obedecer normas.",img:"deber_ninos"},
  {q:"Los niños tienen derecho al JUEGO y la recreación porque:",o:["es obligatorio","ayuda a su desarrollo sano","no sirve para nada","es solo para adultos"],a:1,tip:"El juego es fundamental para el desarrollo físico y mental.",img:"derecho_juego"},
  {q:"Si un niño es maltratado, ¿qué debe hacer?",o:["No decir nada","Contarlo a un adulto de confianza","Pelear","Hacerse el fuerte"],a:1,tip:"Siempre se debe contar a un adulto de confianza (padres, maestros).",img:"maltrato_denunciar"},
  // MODO EXTRA
  {q:"¿Cuál es la capital de la Región Caribe?",o:["Bogotá","Cartagena","Medellín","Cali"],a:1,tip:"Cartagena es una de las principales ciudades de la Región Caribe.",img:"caribe_capital"},
  {q:"¿Qué producto agrícola es famoso de Colombia en todo el mundo?",o:["El arroz","El trigo","El café","La papa"],a:2,tip:"El café colombiano es reconocido mundialmente.",img:"cafe_famoso"},
  {q:"Un NOTICIERO en televisión es un medio de comunicación que:",o:["cuenta cuentos","informa sobre hechos actuales","enseña a cocinar","muestra películas"],a:1,tip:"Los noticieros informan sobre lo que pasa en el país y el mundo.",img:"noticiero"},
  {q:"Los DERECHOS HUMANOS son:",o:["reglas del juego","derechos que tiene toda persona","solo para adultos","solo para niños"],a:1,tip:"Los derechos humanos son para TODAS las personas sin excepción.",img:"derechos_humanos"},
  {q:"¿Por qué es importante la libertad de expresión?",o:["Para decir cualquier cosa sin pensar","Para poder opinar y comunicar ideas respetuosamente","Para gritar siempre","No es importante"],a:1,tip:"La libertad de expresión permite opinar con respeto en una democracia.",img:"libertad_expresion"}
],

  inteligencia_emocional:[
  // MISIÓN 1 — Emociones en contexto social
  {q:"Cuando ganas un juego, sientes:",o:["tristeza","enojo","alegría","miedo"],a:2,tip:"Ganar produce alegría y satisfacción. Es una emoción positiva."},
  {q:"¿Cuál emoción sientes cuando alguien te quita tu turno sin permiso?",o:["alegría","frustración o enojo","amor","sorpresa"],a:1,tip:"La frustración es normal cuando algo no es justo."},
  {q:"La VERGÜENZA es una emoción que sentimos cuando:",o:["estamos muy contentos","hacemos algo que nos parece incorrecto o nos expone","ganamos un premio","comemos mucho"],a:1,tip:"La vergüenza aparece cuando sentimos que hicimos algo mal o nos exponemos."},
  {q:"¿Qué es la ENVIDIA?",o:["querer lo que tiene otra persona","estar muy feliz","tener mucho miedo","no sentir nada"],a:0,tip:"La envidia es querer lo que otro tiene. Es normal sentirla, pero no actuar mal por ella."},
  {q:"Una emoción PRIMARIA es:",o:["una emoción aprendida","una emoción básica con la que nacemos como alegría o miedo","una emoción complicada","una emoción falsa"],a:1,tip:"Emociones primarias: alegría, tristeza, miedo, enojo, asco, sorpresa."},
  // MISIÓN 2 — Comunicación empática
  {q:"¿Qué significa 'escuchar con los ojos'?",o:["leer libros","prestar atención a los gestos y expresiones del otro","no escuchar nada","ver televisión"],a:1,tip:"La comunicación no verbal (gestos, postura) dice mucho sobre cómo se siente alguien."},
  {q:"Cuando alguien está llorando, la respuesta empática es:",o:["reírte","decirle que no llore","preguntarle qué le pasa y ofrecerle apoyo","ignorarlo"],a:2,tip:"Preguntar y ofrecer apoyo demuestra empatía real."},
  {q:"Un 'MENSAJERO ACTIVO' es aquel que:",o:["solo habla","habla Y escucha con atención","nunca escucha","solo escucha"],a:1,tip:"La comunicación efectiva requiere tanto hablar como escuchar activamente."},
  {q:"¿Por qué debemos respetar los turnos para hablar?",o:["no es necesario","para que todos puedan expresarse y ser escuchados","para hablar más rápido","porque la profesora lo dice"],a:1,tip:"Respetar los turnos permite que todos participen y sean escuchados."},
  {q:"El lenguaje corporal representa aproximadamente qué porcentaje de la comunicación:",o:["10%","30%","55% o más","100%"],a:2,tip:"Estudios muestran que más del 55% de la comunicación es no verbal: gestos, postura, expresiones."},
  // MISIÓN 3 — Conflictos y negociación
  {q:"¿Cuál es la diferencia entre un CONFLICTO y un PROBLEMA?",o:["son exactamente lo mismo","un conflicto implica a personas con intereses distintos; un problema puede ser individual","los conflictos son siempre malos","los problemas siempre son más graves"],a:1,tip:"Un conflicto involucra al menos dos personas con necesidades o intereses diferentes."},
  {q:"La MEDIACIÓN en un conflicto es cuando:",o:["nadie ayuda","un tercero neutral ayuda a las partes a encontrar un acuerdo","el más fuerte gana","se llama a la policía siempre"],a:1,tip:"Un mediador neutral ayuda a las partes a comunicarse y llegar a un acuerdo."},
  {q:"¿Qué es el 'ganar-ganar' en la resolución de conflictos?",o:["que alguien siempre pierde","que ambas partes logran lo que necesitan","que nadie gana nada","que el maestro decide"],a:1,tip:"'Ganar-ganar' significa buscar soluciones donde ambas partes queden satisfechas."},
  {q:"Cuando estás en conflicto con alguien, usar 'yo siento...' en vez de 'tú siempre...' sirve para:",o:["no resolver nada","expresar tu sentir sin atacar al otro","ganar la discusión","insultar sin culpa"],a:1,tip:"Los 'Mensajes Yo' comunican el sentimiento propio sin culpar al otro."},
  {q:"¿Cuándo es adecuado pedir ayuda a un adulto en un conflicto?",o:["nunca","solo cuando hay violencia","cuando no pueden resolverlo solos o hay riesgo de daño","siempre, sin intentar primero"],a:2,tip:"Intentar resolver primero, pero pedir ayuda si no es posible o hay riesgo de daño."},
  // MISIÓN 4 — Bienestar emocional
  {q:"El MINDFULNESS o atención plena es:",o:["distraerse constantemente","prestar atención consciente al momento presente sin juzgar","pensar en el futuro siempre","ignorar los sentimientos"],a:1,tip:"El mindfulness ayuda a manejar el estrés prestando atención al aquí y ahora."},
  {q:"¿Qué es la RESILIENCIA?",o:["no sentir ninguna emoción","la capacidad de recuperarse y adaptarse ante las dificultades","rendirse ante los problemas","evitar todos los problemas"],a:1,tip:"La resiliencia es superar las adversidades y salir fortalecido de ellas."},
  {q:"Cuando sientes que una emoción te abruma, una buena estrategia es:",o:["actuar impulsivamente","identificar la emoción, nombrarla y respirar antes de actuar","ignorarla completamente","gritar"],a:1,tip:"Nombrar la emoción ('estoy enojado') ayuda a procesarla mejor."},
  {q:"La AUTOESTIMA es:",o:["creerse mejor que los demás","el valor y amor que te tienes a ti mismo","no importarte nada","odiar a los demás"],a:1,tip:"Autoestima sana = reconocer tu valor sin menospreciar a los demás."},
  {q:"Hacer ejercicio, dormir bien y comer saludable afectan tu bienestar emocional porque:",o:["no tiene ninguna relación","el cuerpo y las emociones están conectados","solo afectan el cuerpo","solo afectan la mente"],a:1,tip:"Cuerpo y mente están interconectados. El bienestar físico favorece el equilibrio emocional."},
  // MODO EXTRA
  {q:"¿Cuál es la diferencia entre SENTIR una emoción y ACTUAR sobre ella?",o:["son lo mismo","sentir es involuntario; cómo actuamos es nuestra responsabilidad","actuar siempre es correcto","sentir está mal"],a:1,tip:"Podemos sentir cualquier emoción; lo que controlamos es cómo respondemos."},
  {q:"¿Qué es la INTELIGENCIA EMOCIONAL según Daniel Goleman?",o:["ser muy inteligente en matemáticas","la capacidad de reconocer y manejar las emociones propias y de los demás","no sentir emociones","tener muchos amigos"],a:1,tip:"Goleman definió la IE como entender y gestionar emociones propias y ajenas eficazmente."},
  {q:"Una persona con alta inteligencia emocional GENERALMENTE:",o:["nunca se enoja","resuelve conflictos mejor y tiene mejores relaciones","no tiene problemas","siempre está feliz"],a:1,tip:"La IE no elimina las emociones difíciles; ayuda a manejarlas mejor."},
  {q:"¿Por qué es importante el autoconocimiento emocional?",o:["no es importante","porque conocer mis emociones me permite gestionarlas mejor","para no sentir nada","para controlar a los demás"],a:1,tip:"Conocer nuestras emociones es el primer paso para gestionarlas saludablemente."},
  {q:"La COMPASIÓN va más allá de la empatía porque:",o:["es menor que la empatía","además de entender el dolor ajeno, motiva a ayudar","es lo mismo que empatía","no existe"],a:1,tip:"Empatía = entender. Compasión = entender + querer ayudar."}
]
,
  // ── GEOMETRÍA MEDIO ──
  geometria:[
  {q:"¿Cómo se calcula el perímetro de un pentágono regular de lado 7 cm?",o:["21 cm","28 cm","35 cm","14 cm"],a:2,tip:"Pentágono regular = 5 lados iguales. Perímetro = 5 × 7 = 35 cm."},
  {q:"¿Cuál es el área de un triángulo rectángulo con catetos de 6 cm y 8 cm?",o:["14 cm²","24 cm²","48 cm²","12 cm²"],a:1,tip:"Área triángulo = (base × altura) ÷ 2 = (6 × 8) ÷ 2 = 24 cm²."},
  {q:"Un polígono REGULAR tiene:",o:["Todos los lados diferentes","Todos los lados y ángulos iguales","Solo algunos lados iguales","Ningún ángulo recto"],a:1,tip:"Polígono regular = todos los lados iguales Y todos los ángulos iguales. Ej: cuadrado, triángulo equilátero."},
  {q:"¿Cuántos ejes de simetría tiene un círculo?",o:["0","4","8","Infinitos"],a:3,tip:"El círculo tiene infinitos ejes de simetría: cualquier línea que pase por el centro es un eje."},
  {q:"El volumen de un cubo de arista 3 cm es:",o:["9 cm³","18 cm³","27 cm³","12 cm³"],a:2,tip:"Volumen cubo = arista³ = 3 × 3 × 3 = 27 cm³."},
  {q:"¿Qué es una RECTA paralela?",o:["Dos rectas que se cruzan","Dos rectas que nunca se cortan y están a la misma distancia","Dos rectas perpendiculares","Una recta curva"],a:1,tip:"Rectas paralelas: misma dirección, nunca se cortan. Como los carriles de una autopista."},
  {q:"El punto A(2,4) está en el cuadrante:",o:["Cuadrante II","Cuadrante IV","Cuadrante I","Cuadrante III"],a:2,tip:"Cuadrante I: x>0 e y>0. A(2,4): x=2 positivo, y=4 positivo → Cuadrante I."},
  {q:"¿Cuántos grados tiene la suma de los ángulos interiores de un triángulo?",o:["90°","180°","270°","360°"],a:1,tip:"La suma de los ángulos interiores de cualquier triángulo siempre es 180°."},
  {q:"Un ROMBO tiene:",o:["4 lados iguales y 4 ángulos rectos","4 lados iguales pero NO necesariamente ángulos rectos","2 lados paralelos solamente","3 lados iguales"],a:1,tip:"El rombo tiene 4 lados iguales pero sus ángulos pueden no ser de 90°. El cuadrado es un rombo especial."},
  {q:"¿Cuál es el área lateral de un cilindro de radio 4 cm y altura 10 cm? (usa π≈3.14)",o:["125.6 cm²","251.2 cm²","502.4 cm²","40 cm²"],a:1,tip:"Área lateral cilindro = 2πrh = 2 × 3.14 × 4 × 10 = 251.2 cm²."},
  {q:"Una TRANSLACIÓN de una figura la:",o:["Rota en un punto","Mueve sin cambiar forma ni tamaño","Hace más grande","La voltea"],a:1,tip:"Una traslación desliza la figura: misma forma, mismo tamaño, diferente posición."},
  {q:"¿Cuántos grados tiene cada ángulo interior de un cuadrado?",o:["45°","60°","90°","120°"],a:2,tip:"El cuadrado tiene 4 ángulos rectos de 90° cada uno. Suma total: 4 × 90° = 360°."},
  {q:"El área de un círculo de radio 5 cm es (π≈3.14):",o:["31.4 cm²","78.5 cm²","15.7 cm²","157 cm²"],a:1,tip:"Área círculo = π × r² = 3.14 × 5² = 3.14 × 25 = 78.5 cm²."},
  {q:"¿Qué tipo de triángulo tiene los 3 lados iguales?",o:["Escaleno","Isósceles","Equilátero","Rectángulo"],a:2,tip:"Equilátero = 3 lados iguales. Isósceles = 2 lados iguales. Escaleno = 3 lados diferentes."},
  {q:"¿Cuántas aristas tiene una pirámide de base cuadrada?",o:["6","8","10","12"],a:1,tip:"Pirámide cuadrada: 4 aristas de la base + 4 aristas laterales = 8 aristas."},
  {q:"Un TRAPECIO tiene exactamente:",o:["0 lados paralelos","1 par de lados paralelos","2 pares de lados paralelos","4 lados paralelos"],a:1,tip:"El trapecio tiene exactamente UN par de lados paralelos llamados bases."},
  {q:"El diámetro de un círculo es:",o:["La mitad del radio","El doble del radio","Igual al radio","El triple del radio"],a:1,tip:"Diámetro = 2 × radio. El diámetro es la cuerda más larga que pasa por el centro."},
  {q:"¿Qué sólido tiene solo una cara curva y ninguna arista?",o:["Cilindro","Cono","Esfera","Pirámide"],a:2,tip:"La esfera no tiene aristas ni vértices, solo una superficie curva perfectamente uniforme."},
  {q:"¿Cuántos grados tiene la suma de los ángulos interiores de un cuadrilátero?",o:["180°","270°","360°","450°"],a:2,tip:"Todo cuadrilátero tiene una suma de ángulos interiores = 360°."},
  {q:"La CIRCUNFERENCIA de un círculo de diámetro 10 cm es (π≈3.14):",o:["31.4 cm","62.8 cm","15.7 cm","10 cm"],a:0,tip:"Circunferencia = π × d = 3.14 × 10 = 31.4 cm."},
  {q:"En el plano cartesiano, el punto (-3, 2) está en:",o:["Cuadrante I","Cuadrante II","Cuadrante III","Cuadrante IV"],a:1,tip:"Q II: x negativo, y positivo. (-3,2): x=-3 (negativo), y=2 (positivo) → Cuadrante II."},
  {q:"¿Qué es una ROTACIÓN de una figura?",o:["Moverla hacia la derecha","Girarla alrededor de un punto fijo","Hacerla más grande","Aplanarla"],a:1,tip:"Rotación = girar la figura alrededor de un punto. Mantiene forma y tamaño, cambia orientación."},
  {q:"El área de un rectángulo de 9 cm × 4 cm es:",o:["13 cm²","26 cm²","36 cm²","72 cm²"],a:2,tip:"Área rectángulo = largo × ancho = 9 × 4 = 36 cm²."},
  {q:"¿Cuántos ángulos tiene un polígono de 7 lados (heptágono)?",o:["5","6","7","8"],a:2,tip:"Todo polígono tiene tantos ángulos como lados. Heptágono = 7 lados = 7 ángulos."},
  {q:"Una REFLEXIÓN o simetría axial transforma una figura en:",o:["Su imagen ampliada","Su imagen espejada respecto a un eje","Una figura diferente","Una rotación"],a:1,tip:"La reflexión es como poner un espejo: la figura resultante es la imagen especular de la original."}
  ],
  // ── LECTURA CRÍTICA MEDIO ──
  lectura_critica:[
  {q:"¿Qué es la ESTRUCTURA de un texto argumentativo?",o:["Solo la introducción","Tesis, argumentos y conclusión","Solo los argumentos","Solo la conclusión"],a:1,tip:"Texto argumentativo: Tesis (posición) → Argumentos (razones y evidencias) → Conclusión (reafirmación)."},
  {q:"La INTERTEXTUALIDAD ocurre cuando:",o:["Un texto es muy largo","Un texto hace referencia a otros textos o autores","Un texto tiene muchos personajes","Un texto es difícil de leer"],a:1,tip:"La intertextualidad conecta textos: cuando un autor cita, alude o parodia otra obra."},
  {q:"¿Qué es el PUNTO DE VISTA en un texto?",o:["El lugar donde está el autor","La perspectiva desde la cual se narra o argumenta","El final de la historia","El número de personajes"],a:1,tip:"El punto de vista es la perspectiva del narrador: primera persona ('yo'), tercera persona ('él/ella'), etc."},
  {q:"Un EUFEMISMO es:",o:["Una palabra técnica","Una expresión suave para referirse a algo considerado desagradable","Un sinónimo exacto","Una metáfora violenta"],a:1,tip:"Eufemismo: palabra más suave para algo difícil. Ej: 'falleció' en vez de 'murió'."},
  {q:"¿Cuál es la función del PÁRRAFO DE CIERRE en un texto?",o:["Introducir el tema","Presentar argumentos nuevos","Resumir y concluir las ideas principales","Solo adornar el texto"],a:2,tip:"El párrafo de cierre sintetiza las ideas principales y refuerza la tesis o mensaje central del texto."},
  {q:"Una HIPÉRBOLE es una figura literaria que:",o:["Compara dos cosas usando 'como'","Exagera la realidad con fines expresivos","Atribuye cualidades humanas a objetos","Usa palabras de significado contrario"],a:1,tip:"Hipérbole = exageración expresiva. Ej: 'Te lo he dicho un millón de veces'."},
  {q:"El TONO de un texto puede ser:",o:["Solo serio o cómico","Irónico, formal, melancólico, esperanzador, crítico, entre otros","Solo positivo o negativo","Solo agresivo o amable"],a:1,tip:"El tono refleja la actitud del autor: puede ser irónico, formal, nostálgico, entusiasta, escéptico, etc."},
  {q:"¿Qué es una FALACIA en un argumento?",o:["Un argumento muy sólido","Un razonamiento con error lógico que parece válido","Una conclusión correcta","Un dato verificable"],a:1,tip:"Una falacia es un error de razonamiento que parece convincente pero no lo es. Ej: 'Todo el mundo lo hace, así que está bien'."},
  {q:"La COHERENCIA textual requiere:",o:["Solo buena gramática","Unidad temática: todas las ideas deben relacionarse con el tema central","Muchos conectores","Párrafos muy largos"],a:1,tip:"Coherencia = las ideas tienen sentido entre sí y se relacionan con el tema. Sin coherencia, el texto es confuso."},
  {q:"¿Qué tipo de texto suele tener un TÍTULO seguido de SUBTÍTULOS con secciones?",o:["Cuento","Artículo informativo o científico","Poema","Obra de teatro"],a:1,tip:"Los textos informativos y científicos usan títulos y subtítulos para organizar la información temáticamente."},
  {q:"Una COMPARACIÓN o SÍMIL usa las palabras:",o:["Por lo tanto / entonces","Como / igual que / parecido a","Sin embargo / aunque","Porque / ya que"],a:1,tip:"El símil compara usando 'como' u otras palabras similares. Ej: 'Corre como el viento'."},
  {q:"El PROPÓSITO de una PUBLICIDAD es principalmente:",o:["Informar objetivamente","Persuadir al consumidor para comprar o adoptar una idea","Entretener sin intención","Dar instrucciones"],a:1,tip:"La publicidad usa técnicas de persuasión: colores, emociones, promesas. Su objetivo es convencer."},
  {q:"¿Qué es la DENOTACIÓN de una palabra?",o:["El significado emocional","El significado literal y objetivo del diccionario","El significado contrario","Un significado inventado"],a:1,tip:"Denotación = significado literal. Connotación = significado adicional emocional o cultural."},
  {q:"Cuando el narrador es uno de los personajes de la historia, usa la:",o:["Tercera persona","Segunda persona","Primera persona","Cuarta persona"],a:2,tip:"Primera persona: el narrador dice 'yo', 'nosotros'. Es uno de los personajes de la historia."},
  {q:"¿Cuál conector indica TIEMPO SIMULTÁNEO?",o:["Después","Antes","Mientras / al mismo tiempo","Finalmente"],a:2,tip:"'Mientras', 'simultáneamente', 'al mismo tiempo' indican que dos cosas ocurren en paralelo."},
  {q:"La IRONÍA ocurre cuando:",o:["Se dice lo contrario de lo que se quiere significar","Se exagera algo","Se comparan dos cosas","Se hace una pregunta retórica"],a:0,tip:"Ironía: decir lo contrario de lo que se piensa, con un tono que evidencia el verdadero significado."},
  {q:"¿Qué distingue un RESUMEN de una SÍNTESIS?",o:["Son iguales","El resumen reproduce las ideas del original; la síntesis las reorganiza con perspectiva propia","El resumen es más largo","La síntesis solo es para textos científicos"],a:1,tip:"Resumen = reducir manteniéndose fiel al original. Síntesis = integrar ideas con perspectiva y reorganización propia."},
  {q:"¿Cuál es la diferencia entre CAUSA y CONSECUENCIA?",o:["Son lo mismo","La causa origina algo; la consecuencia es el resultado de esa causa","La consecuencia viene antes","La causa es el final"],a:1,tip:"Causa → Efecto/Consecuencia. Ej: Causa: llovió mucho. Consecuencia: el río se desbordó."},
  {q:"Un texto es COHESIVO cuando:",o:["Tiene buenas ideas","Las palabras y oraciones se conectan fluidamente (pronombres, conectores, sinónimos)","Solo tiene oraciones cortas","Tiene muchas descripciones"],a:1,tip:"Cohesión = mecanismos que unen el texto: conectores, pronombres, sinónimos, elipsis. Sin cohesión, el texto se lee entrecortado."},
  {q:"¿Qué es la CONNOTACIÓN de una palabra?",o:["Su significado en el diccionario","Los significados adicionales, emocionales o culturales que evoca","Su origen etimológico","Su categoría gramatical"],a:1,tip:"'Serpiente' denota un reptil, pero connota traición, peligro. La connotación va más allá del significado literal."},
  {q:"¿Por qué es importante identificar la FUENTE de un texto?",o:["Para saber cuántas páginas tiene","Para evaluar su credibilidad y confiabilidad","Solo para citarlo correctamente","No es importante"],a:1,tip:"Fuente confiable = la información es más creíble. Fuente desconocida o sesgada = hay que verificar."},
  {q:"Un ARGUMENTO DE AUTORIDAD apoya su posición con:",o:["Solo emociones","Opiniones de expertos o fuentes reconocidas en el tema","Exageraciones","Ejemplos del pasado"],a:1,tip:"Argumento de autoridad: 'Según la OMS...' o 'Los científicos afirman...'. La autoridad de la fuente refuerza el argumento."},
  {q:"¿Qué es la PARÁFRASIS?",o:["Copiar un texto exactamente","Explicar con tus propias palabras lo que dice otro texto","Resumir en una sola oración","Traducir a otro idioma"],a:1,tip:"Parafrasear = expresar las ideas de otro con tus propias palabras, sin copiar literalmente."},
  {q:"¿Cuál es la FUNCIÓN de los SIGNOS DE PUNTUACIÓN en un texto?",o:["Son decorativos","Organizan las ideas, marcan pausas y ayudan a interpretar el texto correctamente","Solo se usan en matemáticas","No tienen función importante"],a:1,tip:"La puntuación cambia el significado: 'No quiero salir.' vs 'No, ¡quiero salir!'"},
  {q:"Un lector CRÍTICO ante un texto de opinión debe:",o:["Creer todo lo que dice","Identificar la posición del autor, evaluar los argumentos y formarse su propia opinión","Ignorar el texto","Solo buscar los datos"],a:1,tip:"Lectura crítica = analizar, evaluar, cuestionar. No aceptar pasivamente sino reflexionar y formar criterio propio."}
  ],
  // ── FÍSICA-QUÍMICA MEDIO ──
  fisica_quimica:[
  {q:"¿Cuál es la fórmula química del agua?",o:["CO2","H2O","NaCl","O2"],a:1,tip:"H₂O: 2 átomos de hidrógeno (H) y 1 de oxígeno (O). El agua es el compuesto más importante para la vida."},
  {q:"La DENSIDAD de un objeto es:",o:["Su peso total","La masa por unidad de volumen (masa ÷ volumen)","Su tamaño","Su temperatura"],a:1,tip:"Densidad = masa ÷ volumen. Si la densidad de un objeto es mayor que la del agua, se hunde; si es menor, flota."},
  {q:"¿Cuál es la diferencia entre MASA y PESO?",o:["Son lo mismo","Masa = cantidad de materia; peso = fuerza gravitacional sobre esa masa","Masa es mayor siempre","El peso no varía nunca"],a:1,tip:"Masa (kg) es constante. Peso varía según la gravedad: en la Luna pesas menos, pero tu masa es igual."},
  {q:"El PUNTO DE EBULLICIÓN del agua al nivel del mar es:",o:["0°C","50°C","100°C","200°C"],a:2,tip:"El agua hierve a 100°C al nivel del mar. A mayor altitud, hierve a menor temperatura por la presión atmosférica."},
  {q:"¿Qué tipo de energía tiene una pelota en movimiento?",o:["Energía potencial","Energía química","Energía cinética","Energía nuclear"],a:2,tip:"Energía cinética = energía del movimiento. Cualquier objeto en movimiento tiene energía cinética."},
  {q:"La LEY DE NEWTON que dice 'toda acción tiene una reacción igual y opuesta' es la:",o:["Primera ley","Segunda ley","Tercera ley","Cuarta ley"],a:2,tip:"3ª Ley de Newton: 'Acción y reacción'. Cuando empujas una pared, la pared te empuja igual de fuerte."},
  {q:"¿Qué proceso convierte un gas en líquido?",o:["Evaporación","Fusión","Condensación","Solidificación"],a:2,tip:"Condensación: gas → líquido. Ocurre cuando el vapor de agua se enfría y forma gotitas (nubes, vaho)."},
  {q:"Una SOLUCIÓN es una mezcla donde:",o:["Los componentes no se mezclan","Un soluto se disuelve completamente en un solvente","Solo hay un componente","Los componentes son sólidos"],a:1,tip:"Solución = mezcla homogénea. El soluto (sal) se disuelve en el solvente (agua). Ej: agua salada."},
  {q:"¿Qué es la PRESIÓN?",o:["La temperatura de un objeto","La fuerza aplicada por unidad de área","El volumen de un gas","La masa de un líquido"],a:1,tip:"Presión = fuerza ÷ área. Un tacón fino ejerce más presión que una sandalia aunque el peso sea igual."},
  {q:"Los METALES generalmente son:",o:["Aislantes eléctricos","Buenos conductores de calor y electricidad","Transparentes","Gaseosos a temperatura ambiente"],a:1,tip:"Los metales conducen calor y electricidad, son maleables (se doblan) y brillantes."},
  {q:"¿Cuál es la unidad de medida de la FUERZA?",o:["Kilogramo","Metro","Newton","Joule"],a:2,tip:"La fuerza se mide en Newtons (N), en honor a Isaac Newton. 1 N = la fuerza para acelerar 1 kg a 1 m/s²."},
  {q:"La FOTOSÍNTESIS transforma:",o:["Oxígeno en CO2","Luz solar, agua y CO2 en glucosa y oxígeno","Minerales en agua","Calor en luz"],a:1,tip:"Fotosíntesis: luz + agua + CO₂ → glucosa + O₂. Las plantas fabrican su alimento usando luz solar."},
  {q:"Un CONDUCTOR eléctrico permite:",o:["Detener el flujo de electricidad","El paso libre de la corriente eléctrica","Almacenar electricidad","Convertir electricidad en calor solamente"],a:1,tip:"Los conductores (metales, grafito, agua con minerales) permiten el paso de la corriente eléctrica."},
  {q:"¿Qué es la ENERGÍA POTENCIAL gravitacional?",o:["Energía del movimiento","Energía almacenada por la posición de un objeto respecto al suelo","Energía del calor","Energía eléctrica"],a:1,tip:"A mayor altura, mayor energía potencial. Al caer, se convierte en cinética. Ej: un libro en un estante."},
  {q:"El CICLO DEL AGUA incluye principalmente:",o:["Solo la lluvia","Evaporación, condensación y precipitación","Solo ríos y mares","Solo nubes"],a:1,tip:"Ciclo del agua: evaporación (agua→vapor) → condensación (vapor→nubes) → precipitación (lluvia/nieve)."},
  {q:"¿Qué produce el ARCO IRIS?",o:["La contaminación del aire","La refracción de la luz solar en las gotas de agua","El viento fuerte","La noche y el día"],a:1,tip:"El arco iris se forma cuando la luz solar se refracta y dispersa en las gotas de lluvia, separándose en colores."},
  {q:"La COMBUSTIÓN es un cambio:",o:["Físico reversible","Químico donde una sustancia reacciona con oxígeno produciendo luz y calor","Solo visual","Físico de temperatura"],a:1,tip:"Combustión = reacción química con O₂. Produce luz y calor, y forma nuevas sustancias. Es irreversible."},
  {q:"¿Cuál es la unidad de medida de la ENERGÍA?",o:["Newton","Metro por segundo","Joule","Pascal"],a:2,tip:"El Joule (J) es la unidad de energía en el Sistema Internacional. 1 J = 1 N × 1 m."},
  {q:"El EFECTO INVERNADERO natural es:",o:["Siempre dañino","Necesario para mantener la temperatura de la Tierra habitable","Solo afecta a los polos","Un fenómeno reciente"],a:1,tip:"El efecto invernadero natural mantiene la Tierra a ~15°C. Sin él, estaría a -18°C. El problema es el exceso humano."},
  {q:"Las ONDAS DE SONIDO necesitan para propagarse:",o:["Ningún medio","Un medio material (sólido, líquido o gas)","Solo el vacío","Solo el aire"],a:1,tip:"El sonido necesita un medio material. En el vacío no hay sonido. Por eso el espacio es silencioso."},
  {q:"¿Qué es un ÁTOMO?",o:["La partícula más pequeña visible a simple vista","La unidad básica de la materia que forma todos los elementos","Un tipo de molécula","Solo una partícula de los gases"],a:1,tip:"El átomo es la unidad básica de la materia. Está compuesto de núcleo (protones y neutrones) y electrones."},
  {q:"La VELOCIDAD DE LA LUZ en el vacío es aproximadamente:",o:["300 km/s","3.000 km/s","300.000 km/s","30.000 km/s"],a:2,tip:"La luz viaja a ≈300.000 km/s en el vacío. Es la velocidad más rápida conocida en el universo."},
  {q:"¿Qué es la BIODEGRADACIÓN?",o:["Producción de energía solar","Descomposición de materiales orgánicos por microorganismos","Contaminación del suelo","Purificación del agua"],a:1,tip:"La biodegradación es la descomposición natural por bacterias y hongos. El papel se biodegrada; el plástico no."},
  {q:"El PUNTO DE FUSIÓN es la temperatura a la que:",o:["Un gas se vuelve líquido","Un líquido se vuelve gas","Un sólido comienza a volverse líquido","Un líquido se vuelve sólido"],a:2,tip:"Punto de fusión: temperatura donde el sólido pasa a líquido. El del hierro es ≈1538°C."},
  {q:"¿Cuál es el gas más abundante en la atmósfera terrestre?",o:["Oxígeno","Dióxido de carbono","Nitrógeno","Argón"],a:2,tip:"El nitrógeno (N₂) constituye el 78% del aire. El oxígeno es el 21%. El CO₂ solo el 0.04%."}
  ],
  // ── FRANCÉS MEDIO ──
  frances:[
  {q:"'Quelle est ta matière préférée?' significa:",o:["¿Cuál es tu color favorito?","¿Cuál es tu materia favorita?","¿Tienes materiales?","¿Dónde estudias?"],a:1,tip:"'Quelle' = cuál. 'Matière' = materia/asignatura. 'Préférée' = favorita."},
  {q:"Completa: 'Je _____ du football avec mes amis.' (jouer)",o:["joue","jouons","jouez","joué"],a:0,tip:"Conjugación de JOUER (jugar): je joue, tu joues, il/elle joue, nous jouons, vous jouez, ils jouent."},
  {q:"¿Cómo se dice 'Mi hermano tiene 10 años' en francés?",o:["Mon frère est dix ans","Mon frère a dix ans","Mon frère fait dix ans","Mon frère ont dix ans"],a:1,tip:"En francés se usa AVOIR (tener) para la edad: 'avoir X ans'. 'Mon frère a dix ans.'"},
  {q:"¿Qué significa 'Je voudrais une pomme, s'il vous plaît'?",o:["Quiero vender una manzana","Quisiera una manzana, por favor","No me gustan las manzanas","¿Tiene manzanas?"],a:1,tip:"'Je voudrais' = me gustaría/quisiera. 'Pomme' = manzana. Frase muy útil en una tienda o restaurante."},
  {q:"El ADJETIVO en francés generalmente va:",o:["Antes del sustantivo siempre","Después del sustantivo (en la mayoría de casos)","Solo al inicio de la oración","Al final de la oración siempre"],a:1,tip:"En francés, la mayoría de adjetivos van DESPUÉS del sustantivo. Ej: 'un livre intéressant' (un libro interesante)."},
  {q:"¿Cómo se llama la torre símbolo de París?",o:["Tour de France","Tour Eiffel","Montmartre","Arc de Triomphe"],a:1,tip:"La Tour Eiffel fue construida en 1889. Es el monumento más visitado del mundo. Symbol de France!"},
  {q:"'Nous allons à l'école en bus' significa:",o:["Vamos a la escuela a pie","Vamos a la escuela en bus","Vamos al bus escolar","La escuela tiene buses"],a:1,tip:"'Nous allons' = vamos (ALLER = ir). 'À l'école' = a la escuela. 'En bus' = en autobús."},
  {q:"¿Cuál es el femenino de 'un étudiant' (un estudiante)?",o:["une étudiante","un étudiant","une étudiant","un étudiantesse"],a:0,tip:"Masculino: étudiant. Femenino: étudiante. En francés muchos sustantivos añaden -e para el femenino."},
  {q:"'Qu'est-ce que tu fais le week-end?' significa:",o:["¿Qué haces durante la semana?","¿Qué haces el fin de semana?","¿Tienes trabajo?","¿Cuándo descansas?"],a:1,tip:"'Qu'est-ce que' = qué. 'Tu fais' = tú haces. 'Le week-end' = el fin de semana."},
  {q:"¿Cómo se dice 'Tengo hambre' en francés?",o:["J'ai peur","J'ai chaud","J'ai faim","J'ai froid"],a:2,tip:"Con AVOIR: J'ai faim (tengo hambre), J'ai soif (tengo sed), J'ai peur (tengo miedo), J'ai chaud (tengo calor)."},
  {q:"¿Cuál es la capital de Francia?",o:["Lyon","Marseille","Paris","Bordeaux"],a:2,tip:"Paris (en francés sin tilde) es la capital de France. Es famosa por la Tour Eiffel, el Louvre y la moda."},
  {q:"¿Qué significa 'le petit-déjeuner'?",o:["El almuerzo","El desayuno","La cena","El merienda"],a:1,tip:"Les repas: le petit-déjeuner (desayuno), le déjeuner (almuerzo), le dîner (cena)."},
  {q:"Completa: 'Elle ___ une robe rouge.' (porter = llevar puesto)",o:["porte","portez","portons","portent"],a:0,tip:"PORTER (llevar): je porte, tu portes, il/elle PORTE. Los verbos en -er se conjugan de esta forma."},
  {q:"¿Cómo se dice 'a la izquierda' en francés?",o:["À droite","Tout droit","À gauche","En face"],a:2,tip:"Directions: à gauche (izquierda), à droite (derecha), tout droit (recto), en face (enfrente)."},
  {q:"'Il fait beau aujourd'hui' significa:",o:["Hace frío hoy","Hace buen tiempo hoy","Está lloviendo hoy","Hay tormenta hoy"],a:1,tip:"La météo: il fait beau (buen tiempo), il fait froid (frío), il fait chaud (calor), il pleut (llueve)."},
  {q:"¿Qué animal es el símbolo nacional de Francia?",o:["El oso","El gallo (le coq)","El lobo","El águila"],a:1,tip:"Le coq gaulois (el gallo galo) es el símbolo nacional de Francia desde la Revolución Francesa."},
  {q:"'Je n'aime pas les épinards' significa:",o:["Me gustan las espinacas","No me gustan las espinacas","Quiero espinacas","Las espinacas son verdes"],a:1,tip:"Negación en francés: NE...PAS. 'Je n'aime PAS' = no me gusta. 'Je n'ai PAS de...' = no tengo."},
  {q:"¿Cómo se dice 'el año' en francés?",o:["Le jour","La semaine","Le mois","L'année / l'an"],a:3,tip:"Le temps: le jour (día), la semaine (semana), le mois (mes), l'année / l'an (año)."},
  {q:"'Combien ça coûte?' significa:",o:["¿Dónde está?","¿Cuánto cuesta?","¿Cómo se llama?","¿Es bueno?"],a:1,tip:"'Combien' = cuánto. 'Ça coûte' = cuesta. Frase esencial para hacer compras en francés."},
  {q:"El número 80 en francés es:",o:["Huitante","Quatre-vingts","Octante","Soixante-dix-dix"],a:1,tip:"El sistema numérico francés es peculiar: 80 = quatre-vingts (4×20). 70 = soixante-dix (60+10). 90 = quatre-vingt-dix."},
  {q:"¿Qué idioma se habla en el país de habla francesa más grande del mundo?",o:["Solo francés","Francés, entre otros idiomas (en países como DR Congo, Canadá, etc.)","Español con acento francés","Un dialecto diferente"],a:1,tip:"Francia no es el país más grande de habla francesa. La República Democrática del Congo y Canadá también son grandes países francófonos."},
  {q:"'Je peux vous aider?' significa:",o:["¿Me puede ayudar?","¿Puedo ayudarle?","¿Quiere ayuda?","¿Necesita algo?"],a:1,tip:"'Je peux' = yo puedo. 'Vous aider' = ayudarle. Frase que usan los vendedores en tiendas."},
  {q:"¿Cuál es la diferencia entre 'TU' y 'VOUS' en francés?",o:["Son exactamente iguales","Tu = informal/singular; Vous = formal o plural","Vous = solo plural","Tu = solo para niños"],a:1,tip:"Tu = tuteo (amigos, familia). Vous = respeto/formal (adultos, desconocidos) o para hablar a varias personas."},
  {q:"'Bonne chance!' significa:",o:["Buen provecho","Buenas noches","Buena suerte","Buenos días"],a:2,tip:"Bonne chance = buena suerte. Bon appétit = buen provecho. Bonne nuit = buenas noches."},
  {q:"¿Cómo se dice 'Hablo un poco de francés' en francés?",o:["Je parle beaucoup français","Je parle un peu français/de français","Je ne parle pas français","Je parle bien français"],a:1,tip:"'Un peu' = un poco. 'Je parle un peu français' es muy útil para decir que eres principiante."}
  ],
  // ── INTELIGENCIA ESPIRITUAL MEDIO ──
  espiritualidad:[
  {q:"El filósofo VIKTOR FRANKL, quien sobrevivió los campos nazis, encontró que la clave para resistir era:",o:["La fuerza física","El sentido o propósito de vida","La riqueza material","La suerte"],a:1,tip:"Frankl desarrolló la Logoterapia: quien tiene un 'por qué' puede soportar cualquier 'cómo'. El sentido da fuerza."},
  {q:"La diferencia entre PLACER y FELICIDAD duradera es:",o:["No hay diferencia","El placer es momentáneo y sensorial; la felicidad profunda viene del sentido y las relaciones","La felicidad es más fácil de lograr","El placer es malo"],a:1,tip:"Aristóteles llamó 'eudaimonía' a la felicidad profunda que viene de una vida con sentido, virtud y conexión."},
  {q:"¿Qué tradición espiritual practica el 'desapego' de los resultados?",o:["Solo el budismo","El concepto aparece en varias tradiciones: budismo, hinduismo, estoicismo","Solo el cristianismo","Ninguna"],a:1,tip:"El desapego = hacer lo mejor posible sin aferrarse obsesivamente al resultado. Aparece en el Gita, el budismo, los estoicos."},
  {q:"La MEDITACIÓN científicamente ha demostrado que:",o:["No tiene efectos comprobados","Reduce el estrés, mejora la concentración y aumenta el bienestar emocional","Solo sirve para dormir","Requiere ser religioso"],a:1,tip:"Estudios de neurociencia (Harvard, MIT) muestran que la meditación regular cambia positivamente la estructura del cerebro."},
  {q:"El concepto de 'IKIGAI' (japonés) se refiere a:",o:["Una técnica de combate","La razón de ser: la intersección de lo que amas, lo que haces bien, lo que el mundo necesita y por lo que te pagan","Una forma de cocinar","Un ritual religioso"],a:1,tip:"Ikigai = 'razón de ser'. Quien lo encuentra vive con más energía, propósito y longevidad. ¡Un regalo de sabiduría japonesa!"},
  {q:"El ESTOICISMO, filosofía de Marco Aurelio, enseña principalmente:",o:["Que nada importa","Que debemos controlar lo que depende de nosotros y aceptar lo que no","Que el placer es lo más importante","Que los demás siempre tienen razón"],a:1,tip:"Epicteto: hay cosas en nuestro poder (juicios, deseos) y cosas fuera de él (clima, lo que otros hacen). Enfócate en las primeras."},
  {q:"¿Qué es la CONTEMPLACIÓN en la tradición espiritual?",o:["Ver televisión atentamente","Una práctica de silencio reflexivo para profundizar en lo esencial de la vida","Un deporte extremo","Una forma de estudio rápido"],a:1,tip:"Contemplar = pausar el ruido exterior e interior para profundizar. Monjes, filósofos y científicos la valoran."},
  {q:"La práctica del AGRADECIMIENTO diario está asociada con:",o:["Solo sentirse bien momentáneamente","Mayor bienestar, optimismo y satisfacción con la vida a largo plazo","Solo la religión","Ignorar los problemas"],a:1,tip:"Estudios de psicología positiva (Emmons, McCullough) muestran que llevar un diario de gratitud mejora significativamente el bienestar."},
  {q:"¿Qué es la 'SABIDURÍA' a diferencia del conocimiento?",o:["Son exactamente iguales","El conocimiento es información; la sabiduría es saber cómo aplicarla bien para vivir mejor","La sabiduría es solo para ancianos","El conocimiento es más valioso"],a:1,tip:"Conocimiento = saber qué. Sabiduría = saber cómo y cuándo actuar bien. La sabiduría integra conocimiento, experiencia y valores."},
  {q:"El concepto budista de IMPERMANENCIA nos dice que:",o:["Todo es eterno","Todo cambia y nada dura para siempre, lo cual puede liberarnos del sufrimiento por el apego","La vida no vale nada","Debemos ignorar el presente"],a:1,tip:"La impermanencia no es pesimista: aceptar que todo cambia nos ayuda a apreciar el presente y no aferrarnos al sufrimiento."},
  {q:"Una persona con 'CARÁCTER' tiene:",o:["Solo buena apariencia","Principios sólidos que mantiene incluso bajo presión o cuando es difícil","Solo talento","Solo buenas intenciones"],a:1,tip:"El carácter es la suma de virtudes practicadas. Aristóteles decía: somos lo que repetidamente hacemos."},
  {q:"¿Qué enseña la FILOSOFÍA del 'UBUNTU' africano?",o:["Que cada persona es completamente independiente","'Soy lo que soy por lo que somos juntos' — la identidad humana se construye en comunidad","Que la competencia es lo más importante","Que los individuos no importan"],a:1,tip:"Ubuntu: 'Yo soy porque nosotros somos'. Una filosofía africana de interdependencia, humanidad y comunidad."},
  {q:"La GENEROSIDAD genuina se distingue porque:",o:["Siempre busca reconocimiento público","Nace del interior sin esperar recompensa ni publicidad","Solo existe si hay dinero de por medio","Es solo para personas ricas"],a:1,tip:"La generosidad auténtica es discreta y desinteresada. Como dijo el poeta: 'La mano izquierda no sabe lo que da la derecha'."},
  {q:"El FLOW o 'experiencia óptima' (Csikszentmihalyi) ocurre cuando:",o:["Estamos muy relajados sin hacer nada","El desafío equilibra exactamente nuestra habilidad, produciendo absorción total y satisfacción","Tenemos mucho tiempo libre","Solo cuando dormimos"],a:1,tip:"Flow = el estado de rendimiento máximo donde el tiempo vuela. Atletas, artistas y científicos lo describen igual."},
  {q:"¿Por qué la NATURALEZA puede ser fuente de experiencias espirituales?",o:["Solo porque es bonita","Porque nos conecta con algo más grande que nosotros, produce asombro y perspectiva","Solo para personas que viven en el campo","No tiene relación con la espiritualidad"],a:1,tip:"El contacto con la naturaleza reduce el cortisol, produce asombro y nos recuerda nuestra pertenencia a algo más grande."},
  {q:"La práctica de 'DECIR LA VERDAD' o veracidad requiere:",o:["Solo no mentir directamente","Valentía, respeto y elección del momento oportuno: la verdad con amor y sabiduría","Herir a los demás sin importar cómo","Decir siempre lo que pensamos sin filtros"],a:1,tip:"La veracidad virtuosa combina honestidad + compasión + sabiduría. La verdad cruel sin amor no es virtud."},
  {q:"¿Qué significa que un niño 'florece' espiritualmente?",o:["Que es muy obediente","Que desarrolla sentido, valores, conexión y capacidad de asombro en su vida","Que estudia mucho","Que es religioso"],a:1,tip:"El florecimiento (eudaimonía) es el desarrollo pleno del ser humano en todas sus dimensiones, incluida la espiritual."},
  {q:"El concepto de 'KARMA' en su sentido filosófico esencial significa:",o:["El destino fijo que no cambiamos","Que nuestras acciones tienen consecuencias que moldean nuestra experiencia futura","La suerte aleatoria","Solo una creencia religiosa sin base"],a:1,tip:"Karma = acción y consecuencia. Nuestros hábitos y acciones crean quiénes somos. No es fatalismo, sino responsabilidad."},
  {q:"¿Qué es la RESILIENCIA ESPIRITUAL?",o:["No sentir dolor nunca","La capacidad de encontrar sentido y crecer incluso en el sufrimiento","Ignorar los problemas","Solo rezar"],a:1,tip:"Viktor Frankl, Nelson Mandela, Helen Keller: encontraron sentido en el sufrimiento y eso les permitió trascenderlo."},
  {q:"La práctica de 'VIVIR EL PRESENTE' o mindfulness ayuda a:",o:["Ignorar el pasado y el futuro completamente","Reducir la ansiedad sobre el futuro y el arrepentimiento del pasado, viviendo más plenamente","Nunca planear","Solo meditar muchas horas"],a:1,tip:"El 80% de nuestro sufrimiento mental viene de rumiaciones del pasado o preocupaciones del futuro. El presente es donde vivimos."},
  {q:"¿Por qué el ARTE puede ser una experiencia espiritual?",o:["Solo entretiene","Porque nos conecta con belleza, verdad y profundidad que van más allá de lo cotidiano","Solo para artistas","No tiene valor espiritual"],a:1,tip:"El arte, la música y la literatura pueden evocar lo inefable: lo que sentimos pero no podemos expresar con palabras."},
  {q:"'Conocerse a uno mismo' (gnoti seauton) fue el mandato inscrito en:",o:["La Biblia","El templo de Delfos en la Grecia antigua","El Corán","La Gran Muralla"],a:1,tip:"'Conócete a ti mismo': lema del oráculo de Delfos. Para Sócrates, el autoconocimiento era la base de toda sabiduría."},
  {q:"¿Cuál es la relación entre VIRTUD y HÁBITO según Aristóteles?",o:["No tienen relación","Las virtudes se desarrollan practicándolas: somos lo que repetidamente hacemos","Las virtudes son innatas","Solo los filósofos pueden ser virtuosos"],a:1,tip:"Aristóteles: 'Somos lo que hacemos repetidamente. La excelencia, entonces, no es un acto sino un hábito.'"},
  {q:"La experiencia del SILENCIO en la vida cotidiana puede:",o:["Ser solo aburrimiento","Permitir el contacto con lo esencial, la creatividad y el autoconocimiento","Ser señal de enfermedad","Solo sirve en lugares religiosos"],a:1,tip:"El silencio es escaso en el mundo moderno pero esencial para pensar con profundidad, crear y conocerse."},
  {q:"¿Qué hace que una vida tenga SIGNIFICADO según la psicología y la filosofía?",o:["Solo el éxito y el dinero","La combinación de conexiones auténticas, crecimiento personal, propósito y contribución a algo mayor que uno mismo","Solo la religión","Solo el placer"],a:1,tip:"Investigaciones de Martin Seligman (PERMA) y Frankl coinciden: significado = relaciones + crecimiento + propósito + contribución."}
  ]

};

// ═══════════════════════════════════════════
//   QD_COMPLEJO — Nivel Complejo (25 preguntas por biome + IE)
// ═══════════════════════════════════════════
const QD_COMPLEJO={
ingles:[
  // MISIÓN 1 — Present perfect, irregular past
  {q:"Choose the correct form: 'I ___ to Paris last year.'",o:["have gone","went","have went","go"],a:1,tip:"Last year = pasado simple. 'Went' es pasado de 'go'.",img:"pp_gone"},
  {q:"Which is the correct PAST PARTICIPLE of 'eat'?",o:["eated","eating","ate","eaten"],a:3,tip:"Eat → ate → eaten. 'Eaten' es el participio pasado.",img:"pp_eaten"},
  {q:"'She has ___ the homework.' (write → past participle)",o:["writed","wrote","writing","written"],a:3,tip:"Write → wrote → written. Participio = written.",img:"pp_written"},
  {q:"Choose the correct sentence:",o:["He has went home.","He has go home.","He has gone home.","He have gone home."],a:2,tip:"Present perfect: has + gone. 'Has gone' = se ha ido.",img:"has_gone"},
  {q:"'I have never ___ sushi.' Which word is correct?",o:["eat","ate","eaten","eating"],a:2,tip:"Después de 'have' se usa el participio pasado: eaten.",img:"never_eaten"},
  // MISIÓN 2 — Conditionals
  {q:"Complete: 'If it rains tomorrow, I ___ an umbrella.'",o:["will take","take","took","taking"],a:0,tip:"First conditional: If + present, will + base verb.",img:"conditional_rain"},
  {q:"'If you study hard, you ___ good grades.'",o:["will get","gets","got","getting"],a:0,tip:"First conditional: If you study (present), you will get (future).",img:"conditional_study"},
  {q:"Choose the correct conditional: 'If she ___ early, she will catch the bus.'",o:["wake up","wakes up","woke up","waking up"],a:1,tip:"En la condición (If clause) usamos presente simple, no futuro.",img:"conditional_wake"},
  {q:"'If I am hungry, I ___ food.'",o:["will eat","eat","ate","eating"],a:0,tip:"First conditional: If + present → will + base verb.",img:"conditional_hungry"},
  {q:"What does 'If it snows, we will make a snowman' mean?",o:["Hace sol ahora","Si nieva en el futuro, haremos muñeco","Estamos haciendo un muñeco","Nunca nieva"],a:1,tip:"Es una condición futura: si nieva → haremos muñeco de nieve.",img:"conditional_snow"},
  // MISIÓN 3 — Reading comprehension with moral
  {q:"📖 'A boy found a wallet with money. Instead of keeping it, he returned it to the owner. The owner was very grateful.' What is the MORAL of this story?",o:["Money is not important","Being honest is rewarding","Never pick up wallets","Lose your wallet"],a:1,tip:"La moraleja: ser honesto (devolver lo que no es tuyo) tiene recompensa.",img:"honest_moral"},
  {q:"📖 'The tortoise and the hare had a race. The hare ran fast but stopped to sleep. The tortoise walked slowly but never stopped. The tortoise won.' What lesson does this teach?",o:["Running fast is bad","Slow and steady wins the race","Sleeping is important","Races are fun"],a:1,tip:"La tortuga ganó por ser constante: 'Slow and steady wins the race'.",img:"tortoise_lesson"},
  {q:"📖 'Lisa shared her lunch with a friend who forgot theirs. The next day, the friend brought cookies for Lisa.' What happened because Lisa was kind?",o:["Nothing","Her friend shared too","She lost her lunch","The teacher got angry"],a:1,tip:"La amabilidad de Lisa hizo que su amiga también compartiera.",img:"kindness_return"},
  {q:"📖 'A small bird had a broken wing. Other birds helped it find food until it healed. When it flew again, it helped another injured bird.' This story is about:",o:["competition","teamwork and helping others","being the strongest","flying fast"],a:1,tip:"El mensaje es sobre la solidaridad y ayudar a los demás.",img:"birds_help"},
  {q:"📖 'Every morning, the farmer woke up early to feed the animals. He never complained because he loved his farm.' The farmer shows:",o:["laziness","responsibility and love for his work","anger","fear"],a:1,tip:"El granjero muestra responsabilidad y amor por su trabajo.",img:"farmer_dedication"},
  // MISIÓN 4 — Writing skills
  {q:"Which sentence is CORRECT?",o:["She don't like pizza.","She doesn't likes pizza.","She doesn't like pizza.","She not like pizza."],a:2,tip:"Tercera persona negativa: doesn't + base verb (sin -s).",img:"correct_neg"},
  {q:"Which sentence is grammatically correct?",o:["They is happy.","They are happy.","They am happy.","They be happy."],a:1,tip:"'They' = plural → usa 'are' (no is, am, o be).",img:"they_are"},
  {q:"Choose the COMPLETE sentence:",o:["Because it was raining.","We stayed home because it was raining.","We stayed home because.","Raining we stayed home."],a:1,tip:"Una oración completa necesita sujeto + verbo + idea completa.",img:"complete_sentence"},
  {q:"Which word correctly completes: 'The children ___ playing in the park.'?",o:["is","are","am","be"],a:1,tip:"'Children' es plural → 'are playing'.",img:"children_playing"},
  {q:"'My sister ___ a beautiful painting yesterday.' Choose the correct verb.",o:["makes","make","made","making"],a:2,tip:"Yesterday = pasado simple. 'Make' → 'made' (irregular).",img:"made_painting"},
  // MODO EXTRA — Mixed advanced
  {q:"Rewrite: 'He is taller than his brother.' This means:",o:["His brother is taller","He is the shortest","His brother is shorter","They are the same height"],a:2,tip:"Si él es 'more tall' que su hermano, su hermano es más bajo.",img:"taller_rewrite"},
  {q:"'I have ___ this movie twice.' (see)",o:["see","saw","seen","seeing"],a:2,tip:"Present perfect: have + past participle. See → saw → seen.",img:"seen_movie"},
  {q:"Which question is formed correctly?",o:["Where you live?","Where do you live?","Where does lives you?","Where living you?"],a:1,tip:"Pregunta: Wh-word + do/does + sujeto + base verb.",img:"correct_question"},
  {q:"'If I ___ a superhero, I would fly.' (past subjunctive)",o:["am","was","were","be"],a:2,tip:"Segundo condicional (irreal): If I were... es correcto aunque suene raro.",img:"if_were"},
  {q:"The OPPOSITE of 'brave' is:",o:["strong","happy","cowardly / timid","fast"],a:2,tip:"Brave = valiente. Opposite = cobarde/tímido.",img:"opposite_brave"}
],
lenguaje:[
  // MISIÓN 1 — Figuras literarias
  {q:"'Sus ojos brillaban como estrellas.' Esta figura literaria es:",o:["una metáfora","una comparación o símil","una personificación","una hipérbole"],a:1,tip:"Usa 'como' para comparar = símil/comparación.",img:"simil_estrellas"},
  {q:"'El sol sonrió en el cielo.' El sol sonriendo es una:",o:["comparación","metáfora","personificación","hipérbole"],a:2,tip:"Dar cualidades humanas a objetos = personificación. El sol no sonríe realmente.",img:"personif_sol"},
  {q:"'Tengo tanta hambre que me comería un caballo.' Es una:",o:["comparación","metáfora","personificación","hipérbole (exageración)"],a:3,tip:"Exagerar mucho = hipérbole. Nadie se come un caballo de verdad.",img:"hiperbola"},
  {q:"'El tiempo vuela cuando estoy contigo.' El tiempo no vuela realmente, es una:",o:["comparación","metáfora","personificación","hipérbole"],a:2,tip:"Dar acción humana al tiempo = personificación.",img:"meta_tiempo"},
  {q:"'Mi abuela es un ángel.' Esta figura literaria compara sin usar 'como':",o:["símil","metáfora","hipérbole","onomatopeya"],a:1,tip:"Comparar sin 'como' = metáfora. Mi abuela = un ángel (bondadosa).",img:"meta_abuela"},
  // MISIÓN 2 — Estructura del párrafo
  {q:"La ORACIÓN PRINCIPAL de un párrafo contiene:",o:["el tema o idea principal","los detalles","la conclusión","el título"],a:0,tip:"La oración principal dice de qué trata el párrafo.",img:"oracion_principal"},
  {q:"Las oraciones de APOYO en un párrafo sirven para:",o:["cambiar el tema","dar detalles y ejemplos","terminar el párrafo","preguntar algo"],a:1,tip:"Las oraciones de apoyo explican, ejemplifican o detallan la idea principal.",img:"oracion_apoyo"},
  {q:"¿Cuál es la CONCLUSIÓN de un párrafo?",o:["La primera oración","Las oraciones del medio","La última oración que resume la idea","El título"],a:2,tip:"La conclusión cierra el párrafo resumiendo la idea principal.",img:"conclusion_parrafo"},
  {q:"Un párrafo debe tratar sobre:",o:["varios temas diferentes","un solo tema","ningún tema","solo preguntas"],a:1,tip:"Un buen párrafo se enfoca en UNA sola idea o tema.",img:"un_tema"},
  {q:"¿Cuál es el orden correcto de un párrafo descriptivo?",o:["Detalles → Tema → Conclusión","Tema → Detalles → Conclusión","Conclusión → Tema → Detalles","Detalles → Conclusión → Tema"],a:1,tip:"Orden: Idea principal → detalles que la apoyan → conclusión.",img:"orden_parrafo"},
  // MISIÓN 3 — Coherencia textual
  {q:"¿Cuál oración NO pertenece al párrafo sobre 'Los perros'? (Tema: perros como mascotas)",o:["Los perros son animales leales.","Me gusta el color rojo.","Los perros necesitan agua y comida.","Jugar con tu perro es divertido."],a:1,tip:"'Me gusta el color rojo' no habla de perros = no es coherente.",img:"incoherente"},
  {q:"¿Qué es la COHERENCIA en un texto?",o:["Usar muchas palabras","Que las ideas estén conectadas y tengan sentido","Tener muchas páginas","Usar sinónimos"],a:1,tip:"Coherencia = las ideas se conectan lógicamente y tienen sentido juntas.",img:"coherencia"},
  {q:"Para que un texto sea COHERENTE, las oraciones deben:",o:["ser muy largas","estar relacionadas con el tema","usar palabras en inglés","ser preguntas"],a:1,tip:"Todas las oraciones deben relacionarse con el tema principal.",img:"oraciones_relacionadas"},
  {q:"¿Cuál es un buen conector para agregar información?",o:["pero","porque","además","entonces"],a:2,tip:"'Además' agrega información nueva sobre el mismo tema.",img:"conector_ademas"},
  {q:"El conector 'por lo tanto' sirve para:",o:["agregar info","contrastar ideas","concluir o dar una consecuencia","iniciar una pregunta"],a:2,tip:"'Por lo tanto' = en conclusión / como consecuencia.",img:"por_lo_tanto"},
  // MISIÓN 4 — Punto de vista
  {q:"Un texto escrito en PRIMERA PERSONA usa:",o:["él/ella","yo, mí, me","usted","nosotros y ellos"],a:1,tip:"Primera persona: yo, mí, me. El narrador es quien cuenta la historia.",img:"primera_persona"},
  {q:"'Él caminó por el bosque y encontró una cueva misteriosa.' Está escrito en:",o:["primera persona","segunda persona","tercera persona","ninguna persona"],a:2,tip:"Usa 'él' = tercera persona. El narrador cuenta la historia de otro.",img:"tercera_persona"},
  {q:"¿Cuál narrador PARTICIPA en la historia?",o:["Tercera persona","Primera persona","Ninguno","Segunda persona"],a:1,tip:"En primera persona (yo), el narrador es parte de la historia.",img:"narrador_participa"},
  {q:"Un cuento que dice 'Yo vi algo increíble...' está contado en:",o:["segunda persona","tercera persona","primera persona","cuarta persona"],a:2,tip:"'Yo' = primera persona. Quien cuenta es parte de la historia.",img:"yo_vi"},
  {q:"¿Cuál NO es un tipo de narrador?",o:["Protagonista (1ra persona)","Omnisciente (sabe todo)","Deletreo","Observador (3ra persona)"],a:2,tip:"'Deletreo' no existe como tipo de narrador. Los otros sí.",img:"tipo_narrador"},
  // MODO EXTRA
  {q:"'El río cantaba entre las rocas.' ¿Qué figura literaria hay?",o:["comparación","hipérbole","personificación","metáfora"],a:2,tip:"Un río no puede cantar = personificación.",img:"rio_canta"},
  {q:"Para conectar dos ideas opuestas, se usa el conector:",o:["y","porque","pero","además"],a:2,tip:"'Pero' conecta ideas opuestas o contrarias.",img:"conector_pero"},
  {q:"¿Cuántas oraciones debe tener como mínimo un párrafo?",o:["una","dos","tres","diez"],a:0,tip:"Un párrafo necesita al menos una oración (la principal).",img:"min_oracion"},
  {q:"'La luna es un espejo plateado.' Es una:",o:["personificación","símil","hipérbole","metáfora"],a:3,tip:"Compara sin 'como' la luna con un espejo = metáfora.",img:"luna_espejo"},
  {q:"¿Qué tipo de narrador sabe los pensamientos de todos los personajes?",o:["Protagonista","Observador","Omnisciente","No existe"],a:2,tip:"El narrador omnisciente lo sabe todo, incluso los pensamientos de cada personaje.",img:"omnisciente"}
],
matematicas:[
  // MISIÓN 1 — Operaciones combinadas
  {q:"Calcula: (8 + 4) × 2 − 3 = ?",o:["21","27","25","23"],a:1,tip:"Primero paréntesis: 8+4=12. Luego multiplicar: 12×2=24. Restar: 24−3=21. Espera: es 21.",img:"combined_ops"},
  {q:"María tiene 3 cajas con 8 chocolates cada una. Regala 5 chocolates. ¿Cuántos le quedan?",o:["29","19","24","13"],a:1,tip:"3×8=24 chocolates. 24−5=19 chocolates.",img:"choc_boxes"},
  {q:"Un edificio tiene 4 pisos con 6 ventanas cada uno. Pintaron 8 ventanas. ¿Cuántas faltan por pintar?",o:["24","16","8","32"],a:1,tip:"Total: 4×6=24. Faltan: 24−8=16 ventanas.",img:"windows_building"},
  {q:"Santiago tiene $50. Compra 2 libros a $18 cada uno. ¿Cuánto le sobra?",o:["$14","$16","$32","$34"],a:0,tip:"2×$18=$36. Sobran: $50−$36=$14.",img:"book_money"},
  {q:"En un estacionamiento hay 3 filas de 10 carros cada una. Llegan 15 más y se van 7. ¿Cuántos carros hay ahora?",o:["30","38","45","23"],a:1,tip:"3×10=30. 30+15=45. 45−7=38 carros.",img:"parking_cars"},
  // MISIÓN 2 — División con resto
  {q:"¿Cuánto es 17 ÷ 5?",o:["Cociente 3, resto 2","Cociente 3, resto 1","Cociente 4, resto 0","Cociente 2, resto 7"],a:0,tip:"17÷5 = 3 con resto 2. Porque 5×3=15 y 17−15=2.",img:"div_17_5"},
  {q:"Repartimos 23 lápices entre 4 niños. ¿Cuántos le tocan a cada uno y cuántos sobran?",o:["5 y sobran 3","6 y sobran 1","5 y sobran 2","4 y sobran 7"],a:0,tip:"23÷4 = 5 con resto 3. 4×5=20, 23−20=3 sobran.",img:"lapices_div"},
  {q:"Si 28 niños forman grupos de 6, ¿cuántos grupos se hacen y cuántos quedan sin grupo?",o:["4 grupos, sobran 4","5 grupos, sobran 2","4 grupos, sobran 5","3 grupos, sobran 10"],a:0,tip:"28÷6 = 4 con resto 4. Hay 4 grupos completos y 4 niños sobran.",img:"grupos_div"},
  {q:"Un pastor tiene 35 ovejas y las reparte en 8 corrales iguales. ¿Cuántas ovejas hay en cada corral?",o:["4 con resto 3","5 con resto 0","3 con resto 11","4 con resto 2"],a:0,tip:"35÷8 = 4 con resto 3. Cada corral tiene 4 ovejas, 3 sobran.",img:"ovejas_div"},
  {q:"¿Cuánto es 50 ÷ 8?",o:["Cociente 6, resto 2","Cociente 5, resto 10","Cociente 7, resto 0","Cociente 6, resto 0"],a:0,tip:"50÷8 = 6 con resto 2. Porque 8×6=48 y 50−48=2.",img:"div_50_8"},
  // MISIÓN 3 — Gráficas
  {q:"📊 Una gráfica de línea muestra la temperatura: Lunes=20°, Martes=22°, Miércoles=18°, Jueves=25°, Viernes=23°. ¿Qué día hizo más frío?",o:["Lunes","Martes","Miércoles","Jueves"],a:2,tip:"18° es la temperatura más baja = Miércoles fue el día más frío.",img:"line_graph_cold"},
  {q:"📊 Si sumas todas las temperaturas (20+22+18+25+23), ¿cuánto da?",o:["100°","108°","98°","110°"],a:1,tip:"20+22+18+25+23 = 108 grados.",img:"temp_sum"},
  {q:"📊 ¿Cuál fue la temperatura MÁXIMA de la semana?",o:["18°","20°","23°","25°"],a:3,tip:"25° es el número más alto = Jueves fue el día más caluroso.",img:"temp_max"},
  {q:"📊 Un pastel circular se divide en partes: 1/2 para fresa, 1/4 para chocolate y 1/4 para vainilla. ¿Qué porcentaje es fresa?",o:["25%","50%","75%","100%"],a:1,tip:"1/2 = 50%. La mitad del pastel es fresa.",img:"pie_chart"},
  {q:"📊 Si el pastel tiene 8 porciones y fresa es la mitad, ¿cuántas porciones son de fresa?",o:["2","3","4","6"],a:2,tip:"La mitad de 8 = 8÷2 = 4 porciones de fresa.",img:"pie_portions"},
  // MISIÓN 4 — Razonamiento lógico
  {q:"Si el patrón es: 2, 6, 18, 54, ___. ¿Qué número sigue?",o:["72","108","162","90"],a:2,tip:"Cada número se multiplica por 3: 54×3=162.",img:"pattern_x3"},
  {q:"Ana es más alta que Bea. Clara es más alta que Ana. ¿Quién es la más baja?",o:["Ana","Bea","Clara","No se puede saber"],a:1,tip:"Clara > Ana > Bea. Bea es la más baja.",img:"height_logic"},
  {q:"Si un número multiplicado por sí mismo da 49, ¿cuál es el número?",o:["6","7","8","9"],a:1,tip:"7×7=49. El número es 7.",img:"square_49"},
  {q:"¿Cuántos triángulos equiláteros hay en la secuencia: 1, 3, 6, 10, __?",o:["13","14","15","16"],a:2,tip:"La diferencia entre números: +2, +3, +4, +5. 10+5=15.",img:"triangle_seq"},
  {q:"Un reloj marca las 9:00. ¿Cuántos grados forma la manecilla grande con las 12:00?",o:["90°","180°","270°","360°"],a:2,tip:"De 12 a 9 = 3/4 de vuelta = 270°.",img:"clock_degrees"},
  // MODO EXTRA — Mixed con pictograma
  {q:"📊 Si al pictograma de aves se le suma un día (sábado con 2 dibujos), ¿cuál es el NUEVO total?",o:["35","36","39","33"],a:2,tip:"33 (original) + 2×3=6 (sábado) = 39 aves en total.",img:"bird_plus",birdRef:true},
  {q:"📊 ¿Qué porcentaje del total de aves (39) se observó el Jueves (12)?",o:["12%","25%","30%","33%"],a:2,tip:"12÷39 ≈ 0.307 = 30.7% ≈ 30%.",img:"bird_percent",birdRef:true},
  {q:"Calcula: 15 × 4 − 30 ÷ 6 =",o:["50","55","60","45"],a:1,tip:"Primero multiplicar y dividir: 15×4=60, 30÷6=5. Luego: 60−5=55.",img:"mixed_ops2"},
  {q:"¿Cuántos minutos hay en 2 horas?",o:["60","100","120","200"],a:2,tip:"1 hora = 60 minutos. 2 horas = 60×2 = 120 minutos.",img:"2_hours"},
  {q:"Un número misterioso: es par, mayor que 20 y menor que 25. ¿Cuál es?",o:["22","24","21","26"],a:0,tip:"Los números pares entre 20 y 25 son 22 y 24. El primero es 22. Puede ser 22 o 24.",img:"mystery_num"}
],
ciencias:[
  // MISIÓN 1 — Método científico
  {q:"El primer paso del método científico es:",o:["Hacer un experimento","Observar y hacer una pregunta","Escribir una conclusión","Comprar materiales"],a:1,tip:"El método científico empieza observando y preguntándose algo.",img:"sci_method1"},
  {q:"Una HIPÓTESIS es:",o:["una respuesta definitiva","una posible explicación que se debe comprobar","un experimento","un dibujo"],a:1,tip:"La hipótesis es una posible respuesta que se prueba con un experimento.",img:"hipotesis"},
  {q:"Después de hacer un experimento, el científico debe:",o:["olvidar los resultados","escribir una conclusión","hacer otra pregunta diferente","comprar más materiales"],a:1,tip:"La conclusión resume lo que se aprendió del experimento.",img:"conclusion"},
  {q:"¿Para qué sirve un EXPERIMENTO en el método científico?",o:["Para dibujar","Para comprobar si la hipótesis es correcta","Para ganar dinero","Para jugar"],a:1,tip:"El experimento prueba si la hipótesis es verdadera o falsa.",img:"experimento"},
  {q:"¿En qué orden va el método científico?",o:["Conclusión → Pregunta → Experimento","Pregunta → Hipótesis → Experimento → Conclusión","Experimento → Pregunta → Conclusión","Hipótesis → Conclusión → Pregunta"],a:1,tip:"Orden: Pregunta → Hipótesis → Experimento → Análisis → Conclusión.",img:"sci_order"},
  // MISIÓN 2 — Magnetismo
  {q:"¿Qué sucede si acercas el polo NORTE de un imán al polo SUR de otro?",o:["Se repelen","Se atraen","No pasa nada","Se rompen"],a:1,tip:"Polos diferentes (Norte y Sur) se ATRAEN.",img:"attract_poles"},
  {q:"¿Qué materiales puede atraer un imán?",o:["Madera, plástico y papel","Hierro, acero y níquel","Agua y aire","Vidrio y cemento"],a:1,tip:"Los imanes atraen metales ferromagnéticos: hierro, acero, níquel, cobalto.",img:"magnet_materials"},
  {q:"Si cortas un imán por la mitad, cada pieza:",o:["pierde su magnetismo","tiene polo norte y polo sur","solo tiene polo norte","se vuelve plástico"],a:1,tip:"Cada pieza tiene su propio polo norte y sur. Siempre tienen ambos polos.",img:"cut_magnet"},
  {q:"Una brújula funciona porque:",o:["tiene un imán adentro que apunta al norte","usa pilas grandes","tiene una luz","es de plástico"],a:0,tip:"La brújula tiene una aguja magnética que siempre apunta al norte magnético.",img:"brujula"},
  {q:"¿Qué es el CAMPO MAGNÉTICO?",o:["Un juego","El área alrededor de un imán donde ejerce fuerza","Un tipo de música","Un deporte"],a:1,tip:"El campo magnético es la zona donde el imán puede atraer metales.",img:"campo_mag"},
  // MISIÓN 3 — Cadenas alimenticias
  {q:"En una cadena alimentaria, los PRODUCTORES son:",o:["los animales carnívoros","las plantas","los humanos","los hongos"],a:1,tip:"Las plantas producen su propio alimento usando la luz del sol = productores.",img:"productores"},
  {q:"Un CONSUMIDOR que come plantas Y otros animales es:",o:["herbívoro","carnívoro","omnívoro","descomponedor"],a:2,tip:"Omnívoro = come de todo (plantas y animales), como el oso o el ser humano.",img:"omnivoro"},
  {q:"Si los ratones desaparecen de un ecosistema, ¿qué podría pasar con las serpientes que se alimentan de ellos?",o:["Nada","Podrían disminuir","Aumentarían","No se afectan"],a:1,tip:"Sin alimento, las serpientes podrían disminuir o irse a otro lugar.",img:"cadena_efecto"},
  {q:"Los DESCOMPONEDORES (como hongos y bacterias) cumplen la función de:",o:["producir oxígeno","reciclar nutrientes al descomponer materia muerta","cazar otros animales","hacer fotosíntesis"],a:1,tip:"Los descomponedores reciclan la materia orgánica muerta en nutrientes para el suelo.",img:"descomponedores"},
  {q:"¿Cuál es el DEPREDADOR en la cadena: pasto → conejo → zorro → águila?",o:["el conejo","el zorro","el águila","el pasto"],a:1,tip:"El depredador del conejo es el zorro (el que lo caza).",img:"depredador"},
  // MISIÓN 4 — Cuidado ambiental
  {q:"¿Cuál de las 3 R es la más importante?",o:["Reducir","Reutilizar","Reciclar","Restaurar"],a:0,tip:"Reducir es la mejor R: si no creamos basura, no hay que reciclar.",img:"tres_r"},
  {q:"El RECICLAJE ayuda a:",o:["crear más basura","contaminar más","ahorrar recursos naturales","quemar cosas"],a:2,tip:"Reciclar reduce la necesidad de extraer nuevos materiales de la naturaleza.",img:"recicla_ayuda"},
  {q:"¿Qué es la CONTAMINACIÓN DEL AGUA?",o:["El agua está muy limpia","Cuando el agua se ensucia con químicos o basura","Cuando llueve mucho","Cuando hay sequía"],a:1,tip:"La contaminación del agua es cuando se ensucia con sustancias tóxicas.",img:"contaminacion"},
  {q:"¿Qué podemos hacer para cuidar el medio ambiente?",o:["Quemar basura","Usar menos plástico y reciclar","Tirar basura en el río","No hacer nada"],a:1,tip:"Reducir plástico, reciclar y ahorrar energía cuida el planeta.",img:"cuidar_planeta"},
  {q:"¿Por qué no debemos quemar basura?",o:["Porque huele rico","Porque contamina el aire y es peligroso","Porque no pasa nada","Porque es rápido"],a:1,tip:"Quemar basura libera gases tóxicos que contaminan el aire.",img:"no_quemar"},
  // MODO EXTRA
  {q:"¿Cuál es la fuente de energía RENOVABLE?",o:["Petróleo","Gas natural","Energía solar","Carbón"],a:2,tip:"La energía solar es renovable porque el Sol siempre estará disponible.",img:"renovable"},
  {q:"El efecto INVERNADERO es:",o:["cuando hace mucho frío","cuando los gases atrapan el calor del Sol y la Tierra se calienta","cuando nieva en verano","cuando el mar se congela"],a:1,tip:"El efecto invernadero atrapa calor y calienta la Tierra.",img:"invernadero"},
  {q:"¿Qué pasa si talamos muchos árboles?",o:["Mejora el aire","Disminuye el oxígeno y aumenta el CO₂","No pasa nada","Llueve más"],a:1,tip:"Los árboles producen oxígeno. Sin ellos, hay más CO₂ y menos oxígeno.",img:"deforestacion"},
  {q:"La CONSERVACIÓN de especies es importante porque:",o:["no es importante","cada especie tiene un rol en el ecosistema","los animales son bonitos","es solo para científicos"],a:1,tip:"Cada especie es importante para mantener el equilibrio del ecosistema.",img:"conservacion"},
  {q:"¿Qué es el DESARROLLO SOSTENIBLE?",o:["usar todos los recursos sin pensar","usar recursos sin agotarlos para el futuro","no usar nada","solo reciclar papel"],a:1,tip:"Desarrollo sostenible = usar recursos de forma responsable para las futuras generaciones.",img:"sostenible"}
],
sociales:[
  // MISIÓN 1 — Organizaciones internacionales
  {q:"La ONU (Organización de las Naciones Unidas) trabaja por:",o:["vender comida","la paz y cooperación entre países","fabricar juguetes","hacer guerras"],a:1,tip:"La ONU busca la paz, los derechos humanos y la cooperación mundial.",img:"onu"},
  {q:"UNICEF es una organización que trabaja por:",o:["los ancianos","los derechos de los niños","los animales","las plantas"],a:1,tip:"UNICEF protege los derechos de los niños en todo el mundo.",img:"unicef"},
  {q:"La Organización Mundial de la Salud (OMS/WHO) se dedica a:",o:["la educación","la salud mundial","el transporte","los deportes"],a:1,tip:"La OMS coordina la salud pública a nivel mundial.",img:"oms"},
  {q:"¿Qué país NO es miembro de la ONU?",o:["Colombia","Brasil","La Antártida","México"],a:2,tip:"La Antártida no tiene país ni gobierno, así que no es miembro de la ONU.",img:"onu_miembros"},
  {q:"Los Derechos Humanos fueron proclamados en:",o:["1789","1948","2000","1810"],a:1,tip:"La Declaración Universal de los Derechos Humanos fue firmada en 1948.",img:"ddhh_1948"},
  // MISIÓN 2 — Derechos humanos en detalle
  {q:"Todos los seres humanos nacen:",o:["libres e iguales","ricos","con los mismos gustos","fuertes"],a:0,tip:"Artículo 1: Todos nacen libres e iguales en dignidad y derechos.",img:"art1_ddhh"},
  {q:"El derecho a la EDUCACIÓN significa que:",o:["solo algunos van a la escuela","todas las personas pueden estudiar","la escuela es obligatoria","no hay escuelas"],a:1,tip:"Todos tienen derecho a la educación, sin discriminación.",img:"derecho_educacion"},
  {q:"¿Qué prohíbe la Declaración de Derechos Humanos?",o:["El derecho a hablar","La tortura y los tratos crueles","Ir a la escuela","Jugar"],a:1,tip:"La Declaración prohíbe la tortura y tratos crueles o degradantes.",img:"no_tortura"},
  {q:"Los derechos humanos son:",o:["solo para adultos","solo para hombres","para TODAS las personas","solo para niños"],a:2,tip:"Los derechos humanos son universales: para todos sin distinción.",img:"universales"},
  {q:"¿Quién defiende los derechos humanos en Colombia?",o:["Solo el presidente","Las instituciones del Estado","Los jueces y tribunales","Solo la policía"],a:1,tip:"Todas las instituciones del Estado deben defender los derechos humanos.",img:"defensa_ddhh"},
  // MISIÓN 3 — Constitución
  {q:"La Constitución de Colombia de 1991 es:",o:["un libro de historia","la ley máxima del país","un poema","una canción"],a:1,tip:"La Constitución es la ley más importante que organiza el país y protege derechos.",img:"const_1991"},
  {q:"La Constitución protege derechos como:",o:["comprar sin pagar","la vida, la libertad y la igualdad","no ir a la escuela","no tener leyes"],a:1,tip:"La Constitución protege la vida, libertad, igualdad y muchos más derechos.",img:"const_protege"},
  {q:"¿Qué pasa si una ley va EN CONTRA de la Constitución?",o:["No pasa nada","La ley no es válida","Se aplica igual","Solo aplica a niños"],a:1,tip:"Las leyes que van contra la Constitución se pueden declarar inválidas.",img:"ley_inconstitucional"},
  {q:"Los DERECHOS FUNDAMENTALES en la Constitución son:",o:["solo para el gobierno","derechos básicos de todas las personas","solo para extranjeros","no son importantes"],a:1,tip:"Los derechos fundamentales son derechos básicos para TODOS los colombianos.",img:"derechos_fund"},
  {q:"La Constitución se puede modificar mediante un proceso llamado:",o:["eliminación","reforma constitucional","borrado","copia"],a:1,tip:"La reforma constitucional es el proceso para cambiar la Constitución.",img:"reforma"},
  // MISIÓN 4 — Resolución de conflictos
  {q:"Cuando hay un conflicto, la mejor forma de resolverlo es:",o:["gritar más fuerte","pelear","hablar y buscar un acuerdo","ignorar al otro"],a:2,tip:"Dialogar y buscar un acuerdo es la forma pacífica de resolver conflictos.",img:"resolver_conflicto"},
  {q:"¿Qué es la NEGOCIACIÓN?",o:["imponer tu voluntad","buscar un acuerdo donde ambos cedan un poco","no hablar","pelear"],a:1,tip:"Negociar = dialogar para llegar a un acuerdo donde ambos ganen algo.",img:"negociacion"},
  {q:"El COMPROMISO en un conflicto significa:",o:["uno gana todo","ambos ceden algo para llegar a un acuerdo","nadie gana","pelean"],a:1,tip:"Comprometerse = ambas partes dan un poco para llegar a un acuerdo justo.",img:"compromiso"},
  {q:"¿Cuál es la función de un MEDIADOR en un conflicto?",o:["pelear por un lado","ayudar a las partes a llegar a un acuerdo","decidir quién gana","ignorar el problema"],a:1,tip:"El mediador escucha ambas partes y ayuda a encontrar solución.",img:"mediador"},
  {q:"La JUSTICIA es importante en la resolución de conflictos porque:",o:["no tiene importancia","asegura que todos sean tratados con equidad","solo beneficia a los ricos","es opcional"],a:1,tip:"La justicia busca que todos sean tratados de manera equitativa y justa.",img:"justicia"},
  // MODO EXTRA
  {q:"¿Qué organización internacional ayuda a los refugiados de guerra?",o:["UNICEF","ACNUR (Alto Comisionado de las Naciones Unidas)","OMS","UNESCO"],a:1,tip:"El ACNUR ayuda a los refugiados y desplazados por conflictos.",img:"acnur"},
  {q:"¿Qué es la PAZ POSITIVA según la Constitución colombiana?",o:["no tener problemas","vivir en democracia con derechos para todos","no hablar","hacer guerra"],a:1,tip:"La paz positiva incluye vivir en democracia con justicia y derechos para todos.",img:"paz_positiva"},
  {q:"¿Qué significa 'Estado Social de Derecho'?",o:["no hay leyes","el Estado protege los derechos de todas las personas","solo hay un gobernante","el Estado hace lo que quiere"],a:1,tip:"Estado de Derecho = las leyes se aplican por igual a todos.",img:"estado_derecho"},
  {q:"La CARTA DE LAS NACIONES UNIDAS fue firmada por Colombia en:",o:["1810","1945","1948","2000"],a:1,tip:"La Carta de la ONU fue firmada en 1945 después de la Segunda Guerra Mundial.",img:"carta_onu"},
  {q:"Cuando alguien viola tus derechos humanos, puedes:",o:["no hacer nada","pedir ayuda a las autoridades competentes","pelear","ignorar"],a:1,tip:"Debes denunciar y pedir ayuda a las autoridades: defensoría del pueblo, policía, jueces.",img:"denunciar"}
],
inteligencia_emocional:[
  // MISIÓN 1 — Reconocer Emociones
  {q:"Sofía no pudo ir al cumpleaños de su amiga. ¿Qué emoción principal siente?",o:["alegría","tristeza","enojo","sorpresa"],a:1,tip:"No poder ir a una fiesta que querías asistir causa tristeza.",img:"tristeza_sofia"},
  {q:"Juan encontró un juguete nuevo en su mochila. ¿Qué emoción sintió?",o:["miedo","enojo","sorpresa y alegría","tristeza"],a:2,tip:"Encontrar algo inesperado causa sorpresa y alegría.",img:"sorpresa_juan"},
  {q:"Cuando alguien te empuja sin razón, es normal sentir:",o:["sueño","enojo","hambre","sueño"],a:1,tip:"El enojo es una emoción natural cuando alguien nos hace daño.",img:"enojo_empujon"},
  {q:"La sensación de que algo malo puede pasar se llama:",o:["alegría","sueño","miedo","hambre"],a:2,tip:"El miedo es la emoción que sentimos ante posibles peligros.",img:"miedo_sensacion"},
  {q:"¿Cuál de estas NO es una emoción?",o:["alegría","tristeza","correr","sorpresa"],a:2,tip:"Correr es una ACCIÓN, no una emoción. Las emociones son sentimientos.",img:"no_emocion"},
  // MISIÓN 2 — Empatía y Comunicación
  {q:"La EMPATÍA es la capacidad de:",o:["enojarse rápido","comprender los sentimientos de los demás","correr muy rápido","dormir mucho"],a:1,tip:"Empatía = ponerse en el lugar del otro y entender cómo se siente.",img:"empatia_def"},
  {q:"Si tu amigo está triste, la mejor forma de mostrar empatía es:",o:["reírte de él","decirle que no llore","escucharlo y apoyarlo","ignorarlo"],a:2,tip:"Escuchar y apoyar es la mejor forma de ayudar a alguien triste.",img:"apoyo_amigo"},
  {q:"¿Qué es la ESCUCHA ACTIVA?",o:["Escuchar música alto","Prestar atención a lo que dice la otra persona","No escuchar nada","Hablar mucho"],a:1,tip:"Escucha activa = prestar toda tu atención al que habla.",img:"escucha_activa"},
  {q:"Un MENSAJE YO es cuando dices:",o:["Tú siempre haces todo mal","Me siento triste cuando me excluyes","No me importa","Eres el mejor"],a:1,tip:"Mensaje Yo: expresa TUS sentimientos sin culpar al otro. 'Yo siento...' ",img:"mensaje_yo"},
  {q:"¿Por qué es importante respetar cuando alguien habla?",o:["No es importante","Para que se sienta valorado y escuchado","Para interrumpirlo","Para aburrirse"],a:1,tip:"Respetar cuando alguien habla es básico para una buena comunicación.",img:"respeto_hablar"},
  // MISIÓN 3 — Resolución de Conflictos
  {q:"Cuando tienes un conflicto con un compañero, el primer paso debe ser:",o:["gritar","respirar profundo y calmarse","pelear","correr"],a:1,tip:"Respirar profundo ayuda a calmarse antes de reaccionar.",img:"respirar_conflicto"},
  {q:"¿Cuál es una buena forma de resolver un conflicto en el recreo?",o:["pelear","buscar un acuerdo donde ambos jueguen","decirle a la profesora sin intentar resolverlo","llorar"],a:1,tip:"Negociar un acuerdo donde ambos puedan jugar es la mejor solución.",img:"conflicto_recreo"},
  {q:"La NEGOCIACIÓN significa:",o:["que uno gana y el otro pierde","que ambos ceden algo para llegar a un acuerdo","que nadie habla","que se pelean"],a:1,tip:"Negociar = buscar un punto medio donde ambos cedan un poco.",img:"negociacion_ie"},
  {q:"Si después de intentar resolver un conflicto no puedes, lo mejor es:",o:["pelear","pedir ayuda a un adulto (profesor, padres)","ignorar el problema","correr"],a:1,tip:"Pedir ayuda a un adulto de confianza es una decisión inteligente y valiente.",img:"pedir_ayuda"},
  {q:"Después de resolver un conflicto, es importante:",o:["no volver a hablar","perdonar y seguir siendo amigos","guardar rencor","contarle a todos el problema"],a:1,tip:"Perdonar y seguir adelante fortalece la amistad.",img:"perdonar_conflicto"},
  // MISIÓN 4 — Auto-regulación
  {q:"Cuando sientes mucho ENOJO, una técnica útil es:",o:["gritar más fuerte","contar hasta 10 lentamente antes de reaccionar","correr muy rápido","llorar muy fuerte"],a:1,tip:"Contar hasta 10 lentamente da tiempo al cerebro para calmarse.",img:"contar_10"},
  {q:"¿Qué es la AUTO-REGULACIÓN emocional?",o:["hacer siempre lo que quiero","manejar mis emociones de forma positiva","no sentir nada","gritar cuando estoy triste"],a:1,tip:"Auto-regulación = controlar mis emociones de forma sana y positiva.",img:"autoregulacion"},
  {q:"Si estás muy nervioso antes de un examen, puedes:",o:["no presentar el examen","respirar profundo y pensar positivo","llorar en clase","salir corriendo"],a:1,tip:"Respirar hondo y pensar positivo ayuda a calmar los nervios.",img:"nervios_examen"},
  {q:"Pedir AYUDA cuando la necesitas es una señal de:",o:["debilidad","valentía e inteligencia","falta de confianza","cobardía"],a:1,tip:"Pedir ayuda es de valientes. Todos necesitamos ayuda a veces.",img:"pedir_ayuda_ie"},
  {q:"La GRATITUD significa:",o:["quejarse de todo","agradecer las cosas buenas que tenemos","querer más cosas","no importarle nada"],a:1,tip:"La gratitud es apreciar lo que tenemos y las personas que nos ayudan.",img:"gratitud"},
  // MODO EXTRA — Mixed IE review
  {q:"¿Qué emoción sientes cuando le regalas un regalo a alguien que se alegra?",o:["tristeza","miedo","satisfacción y alegría","enojo"],a:2,tip:"Hacer feliz a alguien nos produce satisfacción y alegría.",img:"regalo_feliz"},
  {q:"Un compañero no quiere jugar contigo. ¿Cuál es la mejor reacción?",o:["Enojarte y gritarle","Respetar su decisión y buscar otro amigo para jugar","No hablarle nunca más","Llorar"],a:1,tip:"Respetar la decisión del otro y buscar alternativas muestra madurez.",img:"no_quiere_jugar"},
  {q:"La asertividad es la capacidad de:",o:["imponer tus ideas a los demás","expresar tus sentimientos y necesidades con respeto","no decir nunca lo que piensas","gritar fuerte para que te escuchen"],a:1,tip:"Ser asertivo = comunicar lo que sientes y necesitas, respetando a los demás.",img:"asertividad"},
  {q:"Si un amigo te cuenta un problema, lo más empático es:",o:["ignorarlo","decirle que no es importante","escucharlo con atención y preguntarle cómo se siente","cambiar de tema"],a:2,tip:"Escuchar con atención y validar sus sentimientos es ser empático.",img:"escuchar_problema"},
  {q:"¿Cuál es una estrategia de AUTO-REGULACIÓN cuando estás frustrado?",o:["gritar lo más fuerte posible","tirar las cosas","respirar profundo, contar hasta 10 y pedir ayuda si necesitas","no hacer nada"],a:2,tip:"Respirar, contar y pedir ayuda son estrategias saludables para manejar la frustración.",img:"frustracion_estrategia"}
],
  // ── GEOMETRÍA COMPLEJO ──
  geometria:[
  {q:"¿Cuál es la fórmula del área de un trapecio con bases B, b y altura h?",o:["(B+b)×h","(B+b)×h÷2","B×h","(B-b)×h÷2"],a:1,tip:"Área trapecio = (Base mayor + Base menor) × altura ÷ 2. Las dos bases son los lados paralelos."},
  {q:"El volumen de un cilindro de radio 3 cm y altura 8 cm es (π≈3.14):",o:["75.36 cm³","150.72 cm³","226.08 cm³","37.68 cm³"],a:2,tip:"Volumen cilindro = π × r² × h = 3.14 × 9 × 8 = 226.08 cm³."},
  {q:"¿Cuántos grados tienen los ángulos interiores de un hexágono regular?",o:["90°","108°","120°","135°"],a:2,tip:"Ángulo interior polígono regular = (n-2)×180° ÷ n. Para hexágono: (6-2)×180÷6 = 720÷6 = 120°."},
  {q:"La RAZÓN ÁUREA (número φ) es aproximadamente:",o:["3.14","2.71","1.618","1.414"],a:2,tip:"La razón áurea φ ≈ 1.618. Aparece en la naturaleza (flores, conchas) y el arte (Partenón, Mona Lisa)."},
  {q:"¿Cuál es el área de un rombo con diagonales de 12 cm y 8 cm?",o:["96 cm²","48 cm²","20 cm²","24 cm²"],a:1,tip:"Área rombo = (diagonal mayor × diagonal menor) ÷ 2 = (12 × 8) ÷ 2 = 48 cm²."},
  {q:"En el Teorema de Pitágoras, ¿cuál es la hipotenusa?",o:["Cualquier lado del triángulo","El lado opuesto al ángulo recto (el más largo)","El lado más corto","La base del triángulo"],a:1,tip:"Pitágoras: a² + b² = c². La hipotenusa (c) es el lado opuesto al ángulo recto, siempre el más largo."},
  {q:"Si los catetos de un triángulo rectángulo son 3 y 4, ¿cuánto mide la hipotenusa?",o:["5","6","7","3.5"],a:0,tip:"c² = 3² + 4² = 9 + 16 = 25. c = √25 = 5. ¡La terna pitagórica 3-4-5 es la más famosa!"},
  {q:"El volumen de una esfera de radio 6 cm es (π≈3.14):",o:["452.16 cm³","904.32 cm³","150.72 cm³","113.04 cm³"],a:1,tip:"Volumen esfera = (4/3) × π × r³ = (4/3) × 3.14 × 216 = 904.32 cm³."},
  {q:"¿Qué es el ÁNGULO CENTRAL de un círculo?",o:["El ángulo del centro del polígono inscrito","El ángulo formado por dos radios en el centro del círculo","La mitad del ángulo inscrito","El ángulo exterior"],a:1,tip:"El ángulo central tiene su vértice en el centro del círculo y sus lados son dos radios."},
  {q:"¿Cuántos diagonales tiene un hexágono?",o:["6","9","12","15"],a:1,tip:"Diagonales = n(n-3)÷2. Hexágono: 6(6-3)÷2 = 6×3÷2 = 9 diagonales."},
  {q:"La SECCIÓN ÁUREA divide un segmento en dos partes donde:",o:["Ambas partes son iguales","La relación entre el total y la parte mayor es igual a la relación entre la mayor y la menor","La parte menor es el doble de la mayor","No existe relación matemática"],a:1,tip:"En la sección áurea: (a+b)/a = a/b = φ ≈ 1.618. Considerada la proporción más armónica estéticamente."},
  {q:"¿Cuál es la suma de los ángulos interiores de un octógono?",o:["720°","900°","1080°","1260°"],a:2,tip:"Suma ángulos interiores = (n-2) × 180°. Octógono: (8-2) × 180° = 6 × 180° = 1080°."},
  {q:"El área de un sector circular de radio 10 cm y ángulo central 90° es (π≈3.14):",o:["31.4 cm²","78.5 cm²","157 cm²","314 cm²"],a:1,tip:"Área sector = (ángulo/360°) × π × r² = (90/360) × 3.14 × 100 = 0.25 × 314 = 78.5 cm²."},
  {q:"¿Qué es la APOTEMA de un polígono regular?",o:["La longitud de un lado","La distancia del centro al punto medio de un lado","La diagonal","El radio circumscrito"],a:1,tip:"La apotema es la distancia desde el centro del polígono regular hasta el punto medio de cualquier lado."},
  {q:"Dos triángulos son SEMEJANTES cuando:",o:["Tienen el mismo tamaño","Tienen los mismos ángulos pero pueden tener diferente tamaño","Son idénticos en todo","Comparten al menos 2 lados iguales"],a:1,tip:"Triángulos semejantes: mismos ángulos, lados proporcionales. La forma es igual, el tamaño puede diferir."},
  {q:"La TANGENTE de un círculo es una recta que:",o:["Corta el círculo en dos puntos","Toca el círculo en exactamente un punto","Pasa por el centro","No tiene relación con el círculo"],a:1,tip:"La tangente toca el círculo en un único punto y es perpendicular al radio en ese punto."},
  {q:"¿Cuál es el área total de un cubo de arista 5 cm?",o:["25 cm²","125 cm²","150 cm²","100 cm²"],a:2,tip:"Área total cubo = 6 × arista² = 6 × 5² = 6 × 25 = 150 cm²."},
  {q:"¿Cuántos planos de simetría tiene una esfera?",o:["0","6","12","Infinitos"],a:3,tip:"La esfera tiene infinitos planos de simetría: cualquier plano que pase por su centro la divide en dos mitades iguales."},
  {q:"La PROYECCIÓN ORTOGONAL de un sólido es:",o:["Su imagen en un espejo","La representación del sólido vista desde un punto muy lejano (perpendicular)","Su expansión en el plano","Su imagen tridimensional"],a:1,tip:"La proyección ortogonal muestra las vistas frontal, lateral y superior de un sólido desde el infinito."},
  {q:"¿Qué ángulo forman dos rectas PERPENDICULARES?",o:["45°","60°","90°","180°"],a:2,tip:"Rectas perpendiculares se cortan formando 4 ángulos rectos de 90° cada uno."},
  {q:"El TEOREMA DE TALES establece que:",o:["La suma de ángulos de un triángulo es 180°","Rectas paralelas cortadas por una transversal crean segmentos proporcionales","El cuadrado de la hipotenusa es igual a la suma de los cuadrados de los catetos","El área del círculo es π×r²"],a:1,tip:"Tales: rectas paralelas cortadas por transversales crean segmentos proporcionales. Base del concepto de semejanza."},
  {q:"Un POLIEDRO REGULAR o SÓLIDO PLATÓNICO que tiene 8 caras triangulares equiláteras es:",o:["El cubo","El tetraedro","El octaedro","El icosaedro"],a:2,tip:"Los 5 sólidos platónicos: tetraedro(4), cubo(6), octaedro(8), dodecaedro(12), icosaedro(20) caras."},
  {q:"¿Cuál es la diferencia entre ÁREA y VOLUMEN?",o:["Son lo mismo","Área mide superficies (cm²); volumen mide el espacio interior (cm³)","El volumen es siempre mayor","El área incluye el interior"],a:1,tip:"Área = medida de superficie en unidades² (m², cm²). Volumen = espacio interior en unidades³ (m³, cm³)."},
  {q:"La fórmula para el volumen de una pirámide es:",o:["Base × altura","(Base × altura) ÷ 2","(Base × altura) ÷ 3","Base × altura × 2"],a:2,tip:"Volumen pirámide = (Área de la base × altura) ÷ 3. Es un tercio del volumen del prisma equivalente."},
  {q:"¿Cuál es el número de Euler para poliedros convexos: V - A + C = ?",o:["0","1","2","3"],a:2,tip:"Fórmula de Euler: Vértices - Aristas + Caras = 2. Para el cubo: 8 - 12 + 6 = 2. ¡Válido para cualquier poliedro convexo!"}
  ],
  // ── LECTURA CRÍTICA COMPLEJO ──
  lectura_critica:[
  {q:"¿Qué es la DECONSTRUCCIÓN de un texto?",o:["Destruirlo físicamente","Analizar sus capas de significado, contradicciones y supuestos implícitos","Resumirlo brevemente","Traducirlo a otro idioma"],a:1,tip:"Deconstruir: revelar lo que el texto da por sentado, sus tensiones internas y los significados no evidentes."},
  {q:"La ARGUMENTACIÓN AD HOMINEM es una falacia que:",o:["Ataca el argumento con datos","Ataca a la persona en vez del argumento","Usa autoridades válidas","Apela a evidencias reales"],a:1,tip:"Ad hominem: 'Tu argumento no vale porque tú eres...' Es una falacia: la persona y su argumento son independientes."},
  {q:"¿Cuál es la diferencia entre TEXTO ACADÉMICO y TEXTO PERIODÍSTICO?",o:["Son iguales","El académico sigue rigor metodológico y citas formales; el periodístico prioriza la actualidad y claridad","El periodístico es siempre más confiable","El académico no tiene argumentos"],a:1,tip:"Texto académico: metodología, citas, rigor, audiencia especializada. Periodístico: actualidad, claridad, audiencia general."},
  {q:"¿Qué es el ETHOS en la retórica clásica de Aristóteles?",o:["El llamado a las emociones","La credibilidad y autoridad moral del que habla","La lógica del argumento","El contexto del discurso"],a:1,tip:"Aristóteles definió 3 modos de persuasión: Ethos (credibilidad), Pathos (emoción), Logos (lógica)."},
  {q:"Un TEXTO HIPERTEXTUAL se diferencia porque:",o:["Es muy largo","Conecta mediante enlaces con otros textos o recursos de forma no lineal","Solo existe en papel","Usa palabras difíciles"],a:1,tip:"El hipertexto (como páginas web) permite navegar no linealmente mediante hipervínculos a otros textos o recursos."},
  {q:"La PRESUPOSICIÓN en un texto es:",o:["La conclusión explícita","Información que el autor da por sabida sin decirla explícitamente","Una predicción del futuro","Una pregunta sin respuesta"],a:1,tip:"Presuposición: lo que se asume sin decirlo. '¿Sigues llegando tarde?' presupone que ya has llegado tarde antes."},
  {q:"¿Cuál es la función del PRÓLOGO en un libro?",o:["Resumir toda la historia","Introducir al lector, presentar contexto, antecedentes o intenciones del autor","Dar la conclusión final","Solo decorar el libro"],a:1,tip:"El prólogo es un umbral: orienta al lector sobre el contexto, la intención del autor o cómo leer el texto."},
  {q:"La INDUCCIÓN como razonamiento consiste en:",o:["Partir de una ley general para llegar a un caso particular","Partir de casos particulares para llegar a una conclusión general","Usar solo opiniones","Contradecir toda la evidencia"],a:1,tip:"Inducción: observo que el Sol ha salido cada mañana → concluyo que el Sol sale siempre. De lo particular a lo general."},
  {q:"¿Qué es el CONTRATO DE LECTURA de un género textual?",o:["Un acuerdo legal sobre derechos de autor","Las expectativas implícitas que el género crea en el lector sobre cómo leerlo","El número de páginas","El precio del libro"],a:1,tip:"Cada género (novela, artículo científico, fábula) tiene 'reglas no escritas' que lector y autor conocen: el contrato de lectura."},
  {q:"La AMBIGÜEDAD en un texto literario puede ser:",o:["Siempre un error","Un recurso intencional que enriquece el significado con múltiples interpretaciones","Solo una falla de redacción","Algo que debemos eliminar siempre"],a:1,tip:"En literatura, la ambigüedad es riqueza: un mismo pasaje puede leerse de varias formas válidas, todas enriquecedoras."},
  {q:"¿Qué es la POLIFONÍA TEXTUAL?",o:["Muchas voces cantando en un texto musical","La presencia de múltiples voces, perspectivas o discursos en un mismo texto","Solo la voz del narrador","Un defecto de estilo"],a:1,tip:"Polifonía: el texto incluye varias voces (el narrador, los personajes, la sociedad). Bajtín la estudió en Dostoievski."},
  {q:"El ARGUMENTO DE PENDIENTE RESBALADIZA es una falacia que:",o:["Usa evidencia sólida","Afirma sin justificación que un paso pequeño llevará inevitablemente a consecuencias extremas","Apela a la autoridad","Usa estadísticas reales"],a:1,tip:"Pendiente resbaladiza: 'Si hacemos X, entonces inevitablemente pasará Y horrible.' Sin demostrar la cadena causal."},
  {q:"¿Qué significa la POÉTICA de un autor?",o:["Sus poemas publicados","El conjunto de principios, valores y técnicas que guían su manera de crear","Su biografía","Sus temas favoritos solamente"],a:1,tip:"La poética de un autor es su 'filosofía de escritura': qué considera valioso, cómo entiende la literatura y qué técnicas prefiere."},
  {q:"La DEDUCCIÓN como razonamiento consiste en:",o:["Partir de casos específicos","Partir de una premisa general para llegar a una conclusión específica mediante lógica","Solo usar ejemplos","Contradecir las premisas"],a:1,tip:"Deducción: Todos los hombres son mortales (premisa). Sócrates es hombre. Por lo tanto, Sócrates es mortal (conclusión)."},
  {q:"¿Qué es el HORIZONTE DE EXPECTATIVAS de un lector?",o:["El tiempo que tarda en leer","El conjunto de expectativas formadas por lecturas anteriores que influyen en cómo recibe un texto nuevo","El nivel educativo","El gusto personal solamente"],a:1,tip:"Teoría de la recepción (Jauss): el significado se crea en la interacción entre el texto y el horizonte de expectativas del lector."},
  {q:"La GLOBALIZACIÓN del texto informativo actual requiere lectores que:",o:["Solo lean un idioma","Puedan evaluar fuentes diversas, detectar sesgos y contrastar información de múltiples contextos","Memoricen todo","Crean siempre la primera fuente"],a:1,tip:"El lector crítico actual necesita alfabetización mediática: evaluar fuentes, detectar desinformación y contrastar datos."},
  {q:"¿Qué es la ELIPSIS como figura retórica?",o:["Repetición de palabras","Omisión de palabras que se sobreentienden por el contexto","Uso de palabras complicadas","Exageración"],a:1,tip:"Elipsis: omitir palabras sin perder el significado. 'Yo fui al cine y tú [fuiste] al teatro.' Hace el texto más ágil."},
  {q:"Un LECTOR IMPLÍCITO es:",o:["Un lector que no existe","El lector ideal que el autor imagina al escribir, influenciando cómo construye el texto","Solo el editor","El primer lector del manuscrito"],a:1,tip:"Concepto de Wolfgang Iser: cada texto construye su propio lector implícito, el tipo de lector que necesita para ser comprendido plenamente."},
  {q:"¿Cuál es la diferencia entre DISCURSO DIRECTO e INDIRECTO?",o:["No tienen diferencia","Directo cita textualmente; indirecto reformula lo dicho con adaptaciones gramaticales","El indirecto es siempre más preciso","El directo siempre usa comillas invisibles"],a:1,tip:"Directo: 'Martín dijo: «tengo hambre»'. Indirecto: 'Martín dijo que tenía hambre.' El indirecto adapta persona y tiempo verbal."},
  {q:"La INTERTEXTUALIDAD puede ser:",o:["Solo citación directa","Cita, alusión, parodia, pastiche, traducción: múltiples formas de relación entre textos","Solo similitudes de tema","Solo en textos literarios"],a:1,tip:"Tipos de intertextualidad: cita (directa), alusión (indirecta), parodia (humor), pastiche (imitación de estilo)."},
  {q:"¿Qué es la FUNCIÓN METALINGÜÍSTICA del lenguaje?",o:["Hablar sobre el mundo","Hablar sobre el lenguaje mismo usando el lenguaje","Expresar emociones","Dar órdenes"],a:1,tip:"Función metalingüística: cuando el lenguaje se usa para hablar sobre sí mismo. '¿Qué significa esta palabra?' es metalingüístico."},
  {q:"La DISONANCIA COGNITIVA ocurre cuando un lector:",o:["Comprende perfectamente el texto","Enfrenta información que contradice sus creencias previas, generando incomodidad psicológica","Solo lee textos difíciles","No entiende el vocabulario"],a:1,tip:"Festinger: cuando la nueva información contradice nuestras creencias, sentimos incomodidad y buscamos resolverla."},
  {q:"¿Por qué la FIABILIDAD NARRATIVA importa en un texto?",o:["No importa para la comprensión","Un narrador no fiable puede distorsionar la información, y el lector crítico debe detectarlo","Solo importa en textos científicos","Es siempre evidente"],a:1,tip:"Narrador no fiable: su perspectiva es sesgada, limitada o manipuladora. Detectarlo requiere lectura crítica y entre líneas."},
  {q:"¿Qué es la PRAGMÁTICA del lenguaje?",o:["El estudio de la gramática","El estudio de cómo el contexto influye en la interpretación del significado","El estudio del vocabulario","El estudio de la fonética"],a:1,tip:"Pragmática: el mismo enunciado puede significar cosas distintas según el contexto. 'Bonita música' puede ser sarcasmo."},
  {q:"Un lector que puede LEER EL MUNDO además de textos escritos:",o:["Es analfabeto","Interpreta imágenes, símbolos, gestos y situaciones sociales como si fueran textos","Solo lee libros académicos","No necesita leer textos escritos"],a:1,tip:"Paulo Freire: aprender a leer el mundo (la realidad social, política) es tan importante como leer la palabra escrita."}
  ],
  // ── FÍSICA-QUÍMICA COMPLEJO ──
  fisica_quimica:[
  {q:"La SEGUNDA LEY DE LA TERMODINÁMICA establece que:",o:["La energía se crea fácilmente","El desorden (entropía) de un sistema aislado tiende a aumentar con el tiempo","La temperatura siempre baja","La materia se destruye"],a:1,tip:"Entropía = desorden. Todo sistema tiende al máximo desorden. Por eso la habitación se desordena sola pero no se ordena sola."},
  {q:"¿Cuál es la diferencia entre ELEMENTOS y COMPUESTOS?",o:["Son lo mismo","Elementos tienen un solo tipo de átomo; compuestos tienen dos o más tipos de átomos combinados","Los compuestos son más simples","Los elementos no existen en la naturaleza"],a:1,tip:"Elemento: solo un tipo de átomo (O₂, H₂). Compuesto: átomos diferentes combinados (H₂O, CO₂, NaCl)."},
  {q:"La REACCIÓN QUÍMICA de la fotosíntesis se puede escribir como:",o:["H₂O + O₂ → CO₂ + luz","6CO₂ + 6H₂O + luz → C₆H₁₂O₆ + 6O₂","CO₂ + H₂O → O₂","Glucosa → CO₂ + H₂O"],a:1,tip:"Fotosíntesis: 6CO₂ + 6H₂O + energía luminosa → C₆H₁₂O₆ (glucosa) + 6O₂. Plantas convierten luz en alimento."},
  {q:"El NÚMERO ATÓMICO de un elemento indica:",o:["El número de neutrones","El número de protones en el núcleo","La masa del átomo","El número de electrones solamente"],a:1,tip:"Número atómico (Z) = número de protones. Define el elemento: el hidrógeno tiene Z=1, el oxígeno Z=8."},
  {q:"¿Qué es la HOMEOSTASIS en los organismos vivos?",o:["El crecimiento del organismo","La capacidad de mantener condiciones internas estables ante cambios externos","La reproducción","Solo la temperatura corporal"],a:1,tip:"Homeostasis: el cuerpo regula temperatura, pH, glucosa, etc. para mantener el equilibrio interno. Es vital para la vida."},
  {q:"La LEY DE CONSERVACIÓN DE LA ENERGÍA establece que:",o:["La energía se crea y destruye constantemente","La energía total de un sistema aislado permanece constante; solo se transforma","La energía siempre se pierde como calor","Solo la energía cinética se conserva"],a:1,tip:"La energía no se crea ni se destruye, solo se transforma. Energía eléctrica → luz (bombilla). La suma total es constante."},
  {q:"¿Cuál es la diferencia entre ACIDEZ y BASICIDAD de una solución?",o:["No hay diferencia","Los ácidos tienen pH<7 (dan iones H⁺); las bases tienen pH>7 (dan iones OH⁻)","Las bases son siempre peligrosas","Los ácidos son siempre inofensivos"],a:1,tip:"pH<7: ácido (vinagre, jugo limón). pH=7: neutro (agua pura). pH>7: básico/alcalino (bicarbonato, lejía)."},
  {q:"¿Qué es la RADIOACTIVIDAD?",o:["Ondas de radio","La emisión espontánea de partículas o radiación por núcleos atómicos inestables","La energía solar","Solo la energía nuclear de las bombas"],a:1,tip:"Radioactividad: núcleos inestables emiten partículas (alfa, beta) o radiación gamma al buscar estabilidad. Descubierta por Marie Curie."},
  {q:"El PRINCIPIO DE ARQUÍMEDES dice que:",o:["Todo objeto cae a la misma velocidad","Un objeto sumergido experimenta un empuje hacia arriba igual al peso del fluido desplazado","La presión aumenta con la temperatura","Los gases no tienen peso"],a:1,tip:"Arquímedes: el empuje = peso del fluido desplazado. Por eso los barcos flotan: desplazan tanto agua que el empuje iguala su peso."},
  {q:"¿Qué es la TENSIÓN SUPERFICIAL?",o:["La presión del agua en profundidad","La fuerza cohesiva entre moléculas de un líquido que crea una 'película' en su superficie","La temperatura del agua","El peso del agua"],a:1,tip:"La tensión superficial permite que un mosquito camine sobre el agua o que las lágrimas formen gotas. Es la cohesión molecular."},
  {q:"La LEY DE LA GRAVITACIÓN UNIVERSAL de Newton establece que:",o:["Solo la Tierra atrae a los objetos","Todos los objetos con masa se atraen mutuamente con una fuerza proporcional a sus masas e inversamente proporcional a su distancia²","La gravedad solo afecta grandes masas","Los objetos sin masa también se atraen"],a:1,tip:"F = G(m₁×m₂)/r². Todo tiene gravedad: tú atraes a la Tierra tanto como ella te atrae a ti. La distancia reduce la fuerza."},
  {q:"¿Qué son los ISÓTOPOS de un elemento?",o:["Elementos diferentes con propiedades similares","Átomos del mismo elemento con el mismo número de protones pero diferente número de neutrones","Moléculas con la misma fórmula","Compuestos con los mismos elementos"],a:1,tip:"Isótopos: mismo elemento (mismos protones), diferente número de neutrones. El carbono-14 (C-14) es usado en datación arqueológica."},
  {q:"¿Qué describe la LEY DE HOOKE para un resorte?",o:["El resorte siempre rebota igual","La fuerza elástica es proporcional al alargamiento: F = k × x","Los resortes no tienen ley","Solo aplica a materiales líquidos"],a:1,tip:"Ley de Hooke: F = k × x. Duplicas la extensión → duplicas la fuerza. Válido hasta el límite elástico del material."},
  {q:"¿Cuál es la diferencia entre CALOR y TEMPERATURA?",o:["Son sinónimos perfectos","Temperatura mide la energía cinética promedio de las moléculas; calor es la transferencia de energía térmica","El calor es siempre mayor","La temperatura es la causa del calor siempre"],a:1,tip:"Temperatura = qué tan energéticas están las moléculas. Calor = energía que fluye de un cuerpo caliente a uno frío."},
  {q:"El EFECTO DOPPLER ocurre cuando:",o:["Una onda viaja en el vacío","La frecuencia percibida de una onda cambia cuando la fuente o el receptor se mueven","Las ondas se amplifican","Solo con ondas de luz"],a:1,tip:"Efecto Doppler: cuando una ambulancia se acerca, el sonido se oye más agudo (mayor frecuencia); al alejarse, más grave."},
  {q:"¿Qué es la ÓSMOSIS?",o:["Movimiento de soluto de mayor a menor concentración","Movimiento de agua a través de una membrana semipermeable de menor a mayor concentración de soluto","La evaporación del agua","La disolución de sales"],a:1,tip:"Ósmosis: el agua atraviesa membranas semipermeables buscando equilibrar concentraciones. Vital para las células vivas."},
  {q:"La PRIMERA LEY DE NEWTON o 'ley de inercia' establece que:",o:["Todo objeto acelera continuamente","Un objeto en reposo o movimiento uniforme continúa así a menos que actúe una fuerza externa neta","La fuerza es igual a la masa por la aceleración","A toda acción hay una reacción igual y opuesta"],a:1,tip:"Inercia: los objetos 'resisten' cambiar su estado. Por eso, al frenar bruscamente, tu cuerpo sigue hacia adelante."},
  {q:"¿Cuál es la relación entre FRECUENCIA y LONGITUD DE ONDA en una onda?",o:["Son directamente proporcionales","Son inversamente proporcionales: v = f × λ","No tienen relación","Son siempre iguales"],a:1,tip:"v = f × λ (velocidad = frecuencia × longitud de onda). Si la frecuencia sube, la longitud de onda baja (misma velocidad)."},
  {q:"La ESPECTROSCOPÍA permite a los científicos:",o:["Medir la temperatura del aire","Identificar elementos por la luz que absorben o emiten","Solo ver objetos pequeños","Crear nuevos elementos"],a:1,tip:"Cada elemento emite un espectro único (como una huella dactilar). Así sabemos qué elementos hay en las estrellas distantes."},
  {q:"¿Qué es la CAPILARIDAD?",o:["La presión del agua en tuberías","El fenómeno por el cual los líquidos ascienden en tubos estrechos por adhesión y cohesión","Solo la absorción de agua por plantas","La evaporación en espacios cerrados"],a:1,tip:"La capilaridad hace que el agua suba por los vasos xilema de las plantas y por la mecha de una vela. Es adhesión + cohesión."},
  {q:"¿Cuál es la diferencia entre FUSIÓN NUCLEAR y FISIÓN NUCLEAR?",o:["Son lo mismo","Fusión: dos núcleos se unen; fisión: un núcleo pesado se divide. El Sol usa fusión; las plantas atómicas usan fisión","La fisión une núcleos","La fusión divide núcleos"],a:1,tip:"El Sol fusiona hidrógeno en helio, liberando enorme energía. Las centrales nucleares fisionan uranio. La fusión es más eficiente y limpia."},
  {q:"¿Qué es la DIFRACCIÓN de la luz?",o:["La reflexión en espejos planos","El fenómeno por el cual la luz se dobla al pasar por una rendija o alrededor de obstáculos","La refracción en el agua","La absorción de luz por objetos oscuros"],a:1,tip:"Difracción: la luz se 'dobla' al pasar por aberturas pequeñas o bordes de obstáculos. Prueba de la naturaleza ondulatoria de la luz."},
  {q:"La TABLA PERIÓDICA organiza los elementos principalmente por:",o:["Tamaño del átomo","Número atómico creciente y propiedades similares en columnas (grupos)","Orden alfabético","Abundancia en la naturaleza"],a:1,tip:"Mendeleiev (1869) organizó los elementos por número atómico y propiedades. Los grupos (columnas) tienen propiedades similares."},
  {q:"¿Qué es el CAMPO MAGNÉTICO?",o:["El calor generado por imanes","La región del espacio alrededor de un imán o corriente eléctrica donde se ejercen fuerzas magnéticas","Solo el magnetismo terrestre","La atracción entre cargas eléctricas"],a:1,tip:"El campo magnético rodea imanes y conductores con corriente. La Tierra tiene campo magnético que protege del viento solar."},
  {q:"¿Cuál es el principio del LÁSER?",o:["Luz solar concentrada","Emisión estimulada de luz coherente y monocromática amplificada","Reflexión en espejos curvos","Fluorescencia química"],a:1,tip:"LASER = Light Amplification by Stimulated Emission of Radiation. La luz láser es coherente (misma fase) y monocromática (mismo color)."}
  ],
  // ── FRANCÉS COMPLEJO ──
  frances:[
  {q:"¿Cuál es la diferencia entre PASSÉ COMPOSÉ y IMPARFAIT?",o:["Son tiempos iguales","Passé composé: acción puntual completada; imparfait: acción habitual o descripción en el pasado","Imparfait es más formal","Passé composé solo con AVOIR"],a:1,tip:"P.C.: 'Hier, j'ai mangé une pizza' (acción puntual). Imparfait: 'Quand j'étais petit, je jouais dehors' (hábito pasado)."},
  {q:"El verbo ÊTRE se conjuga en présent como:",o:["je suis, tu es, il est, nous sommes, vous êtes, ils sont","je suis, tu ais, il ait, nous avons, vous avez, ils ont","je ai, tu as, il a, nous être, vous êtes, ils étaient","je était, tu était, il était"],a:0,tip:"ÊTRE (ser/estar): je suis, tu es, il/elle EST, nous SOMMES, vous ÊTES, ils/elles SONT. ¡Irregular, hay que memorizarlo!"},
  {q:"¿Cuál es la diferencia entre 'SAVOIR' y 'CONNAÎTRE'?",o:["Son sinónimos perfectos","Savoir = saber algo abstracto/habilidad; Connaître = conocer una persona, lugar o cosa concreta","Connaître es más formal","Savoir solo se usa en preguntas"],a:1,tip:"Je SAIS conduire (sé conducir - habilidad). Je CONNAIS Paris (conozco París - lugar). Je CONNAIS Marie (conozco a Marie - persona)."},
  {q:"'Si j'avais de l'argent, j'achèterais une voiture' usa el modo:",o:["Indicativo","Conditionnel (condicional presente)","Subjonctif","Impératif"],a:1,tip:"El conditionnel présent expresa hipótesis y deseos. Si + imparfait → conditionnel présent. 'Si tuviera dinero, compraría...'"},
  {q:"¿Qué son los PRONOMBRES RELATIFS 'qui' y 'que'?",o:["Artículos del francés","Palabras que relacionan una oración subordinada con un antecedente: QUI (sujeto), QUE (objeto)","Preposiciones","Solo aparecen en preguntas"],a:1,tip:"QUI reemplaza el sujeto: 'L'homme QUI parle' (el hombre que habla). QUE reemplaza el objeto: 'Le livre QUE je lis' (el libro que leo)."},
  {q:"El SUBJONCTIF en francés se usa típicamente después de:",o:["Verbos de certeza como 'je sais que'","Verbos de duda, deseo, emoción o voluntad: 'je veux que', 'il faut que', 'je doute que'","Todos los verbos","Solo en exclamaciones"],a:1,tip:"Subjonctif: 'Je veux QU'IL VIENNE' (quiero que venga). Expresa subjetividad, duda, deseo, emoción. 'Il faut que tu PARTES.'"},
  {q:"¿Cuál es la función del PRONOM COD en francés?",o:["Indica el tiempo","Reemplaza el complemento directo para evitar la repetición","Indica el lugar","Introduce una pregunta"],a:1,tip:"COD (Complément d'Objet Direct): 'Je mange la pomme' → 'Je LA mange.' LA reemplaza 'la pomme' para evitar repetir."},
  {q:"¿Qué significa 'VOUVOYER' a alguien?",o:["Tutearlo (usar 'tu')","Tratarlo formalmente usando 'vous' en singular","Ignorarlo","Hablarle en inglés"],a:1,tip:"En francés hay dos formas de dirigirse a alguien: TUTOYER (usar tu, informal) o VOUVOYER (usar vous, formal/respeto)."},
  {q:"El GÉNITIF SAXON en francés se expresa con:",o:["Apostrofe como en inglés","La preposición 'DE': 'le livre DE Marie' (el libro de Marie)","Solo con AVOIR","Con ÊTRE + nom"],a:1,tip:"Posesión en francés: 'le livre DE Marie' = el libro de Marie. No hay 's como en inglés. Se usa DE + nombre."},
  {q:"'Ne... que' en francés expresa:",o:["Negación total","Restricción: 'solo/solamente'. 'Je ne parle QUE français' = Solo hablo francés","Duda","Afirmación fuerte"],a:1,tip:"Ne...que = restricción. 'Il ne mange QUE des légumes' = Solo come verduras. No es negación completa, es restricción."},
  {q:"¿Qué es la LIAISON en francés?",o:["Un tipo de pastel francés","La pronunciación de una consonante final normalmente muda cuando la siguiente palabra empieza por vocal","Una conjunción","Un modo verbal"],a:1,tip:"Liaison: 'vous_avez' = [vuzave], 'les_amis' = [lezami]. La 's' o 'z' se pronuncia enlazando con la vocal siguiente."},
  {q:"La frase 'Malgré tout, il a réussi' significa:",o:["Porque todo salió bien, tuvo éxito","A pesar de todo, tuvo éxito","Sin hacer nada, tuvo éxito","Todo el mundo le ayudó a tener éxito"],a:1,tip:"'Malgré' = a pesar de. 'Malgré tout' = a pesar de todo. Indica contraste entre obstáculos y resultado positivo."},
  {q:"¿Cuál es el ACCORD du participe passé con AVOIR?",o:["Siempre acuerda en género y número","Acuerda con el COD cuando este va ANTES del verbo. Si va después, no hay acuerdo","Nunca acuerda","Solo acuerda con el sujeto"],a:1,tip:"'La lettre QUE j'ai ÉCRITE' (la carta que escribí) - ÉCRITE acuerda con 'lettre' (femenino) porque el COD va antes."},
  {q:"¿Qué son los ADVERBES EN -MENT?",o:["Adjetivos femeninos","Adverbios formados añadiendo -MENT al femenino del adjetivo (≈ -mente en español)","Verbos irregulares","Solo palabras negativas"],a:1,tip:"Lent → lente → lentement (lentamente). Rapide → rapidement. Comme en español: -ment ≈ -mente. Mais: bien, mal, vite son irregulares."},
  {q:"La frase 'Plus je lis, plus je comprends' significa:",o:["Nunca leo porque no entiendo","Cuanto más leo, más comprendo","Prefiero leer a entender","Leo pero no entiendo"],a:1,tip:"Structure 'Plus... plus': expresa proporcionalidad. 'Plus je lis, PLUS je comprends' = cuanto más... más. Muy usada en francés."},
  {q:"¿En qué se diferencia el FUTUR SIMPLE del FUTUR PROCHE?",o:["No hay diferencia","Futur proche: aller + infinitivo (evento inmediato); futur simple: para eventos más lejanos o ciertos","Futur simple es informal","Futur proche es solo para planes escritos"],a:1,tip:"Futur proche: 'Je vais partir' (voy a partir - hoy). Futur simple: 'Je partirai demain' (partiré - evento más formal o lejano)."},
  {q:"¿Qué son los TEMPS COMPOSÉS en francés?",o:["Tiempos simples del verbo","Tiempos formados con un auxiliaire (avoir o être) + participe passé","Solo el passé composé","Los tiempos del subjonctif"],a:1,tip:"Temps composés: passé composé, plus-que-parfait, futur antérieur... todos usan auxiliaire + participe passé."},
  {q:"'À condition que' + subjonctif expresa:",o:["Una causa","Una condición necesaria para que algo ocurra","Una consecuencia","Una descripción"],a:1,tip:"'Je t'aide à condition que tu travailles' = te ayudo con la condición de que trabajes. Conditionnel: à condition que, pourvu que, à moins que."},
  {q:"¿Cuál es la diferencia entre 'IL Y A' e 'IL Y AVAIT'?",o:["No tienen diferencia","Il y a: presente (hay); il y avait: imperfait (había/solía haber)","Il y avait es más formal","Il y a solo se usa en preguntas"],a:1,tip:"Il y a = hay (ahora). Il y avait = había (antes, imperfait, descripción). Il y a eu = hubo (passé composé, evento puntual)."},
  {q:"¿Qué expresa el PLUS-QUE-PARFAIT (pluscuamperfecto)?",o:["El futuro","Una acción pasada anterior a otra acción pasada","El presente habitual","Un deseo futuro"],a:1,tip:"Plus-que-parfait: 'Quand il est arrivé, j'avais déjà mangé' = Cuando llegó, yo ya había comido. Pasado anterior al pasado."},
  {q:"La FRANCOPHONIE incluye países donde:",o:["Solo se habla francés como lengua materna","El francés es lengua oficial, de enseñanza o ampliamente usada, aunque no sea la única lengua","Solo está en Europa","Solo incluye las antiguas colonias"],a:1,tip:"La Francophonie agrupa 88 estados. Incluye Bélgica, Suiza, Canadá, Senegal, Marruecos, Madagascar... ¡88 países!"},
  {q:"¿Cuál es la función del PRONOM Y en francés?",o:["Reemplaza a una persona","Reemplaza un complemento de lugar o un complemento introducido por 'à' no-personal","Reemplaza el sujeto","Solo aparece en negaciones"],a:1,tip:"Y reemplaza un lugar o complemento con 'à': 'Tu vas à Paris?' → 'Tu Y vas?' Y = au marché, en France, à l'école."},
  {q:"¿Qué caracteriza al ALEXANDRIN, el verso más clásico de la poesía francesa?",o:["6 sílabas","12 sílabas divididas en dos hemistiquios de 6","8 sílabas","Versos sin métrica fija"],a:1,tip:"El alexandrin tiene 12 sílabas (6+6). Racine, Corneille, Hugo lo usaron. 'Je le vis, je rougis, je pâlis à sa vue.' = 6+6."},
  {q:"En la nouvelle vague du cinéma français, cinéastes comme Godard innovaron porque:",o:["Siguieron exactamente el cine clásico","Rompieron las convenciones: montaje discontinuo, actores no profesionales, improvisación, temas contemporáneos","Usaron más presupuesto","Filmaron solo en estudios"],a:1,tip:"La Nouvelle Vague (años 60): Godard, Truffaut. Cámara en mano, exteriores reales, guión libre. Revolucionó el cine mundial."},
  {q:"¿Qué es la CHANSON FRANÇAISE como género cultural?",o:["Solo música pop","Un género musical con énfasis en la letra poética, la actuación y temas como el amor, la vida, la sociedad","Solo canciones infantiles","Música clásica francesa"],a:1,tip:"Edith Piaf, Jacques Brel, Georges Brassens: la chanson française prioriza las letras como poesía. La voz y las palabras son el corazón."}
  ],
  // ── INTELIGENCIA ESPIRITUAL COMPLEJO ──
  espiritualidad:[
  {q:"¿Cuál es la diferencia entre ÉTICA y MORAL según la filosofía?",o:["Son exactamente iguales","Moral: conjunto de normas y valores de una comunidad; ética: reflexión filosófica crítica sobre esas normas","La ética es religiosa; la moral es laica","La moral es individual; la ética es colectiva siempre"],a:1,tip:"Moral = las normas. Ética = la pregunta sobre esas normas: ¿por qué estas normas y no otras? ¿Son justas? ¿Cómo vivir bien?"},
  {q:"El IMPERATIVO CATEGÓRICO de Kant propone:",o:["Actuar según las consecuencias que deseamos","Actuar solo según normas que pudiéramos querer que fueran universales para todos","Actuar según el placer","Actuar según la autoridad"],a:1,tip:"Kant: '¿Puedo querer que mi acción se convierta en ley universal?' Si todos mintieran cuando conviene, la confianza desaparecería."},
  {q:"¿Qué es el NIHILISMO y qué respuesta propone Nietzsche?",o:["La afirmación de que todo tiene sentido","El nihilismo: nada tiene sentido inherente. Nietzsche responde: crea tu propio sentido con la voluntad de poder","La creencia en Dios","El optimismo absoluto"],a:1,tip:"Nietzsche: tras la 'muerte de Dios' (valores absolutos caídos), el superhombre crea sus propios valores con valentía y creatividad."},
  {q:"¿Qué es la FENOMENOLOGÍA según Husserl?",o:["El estudio de los fenómenos físicos","El estudio de los fenómenos tal como aparecen a la conciencia, entre paréntesis los presupuestos previos","La ciencia de los volcanes","Una rama de la psicología conductista"],a:1,tip:"Fenomenología: 'volver a las cosas mismas', describir la experiencia pura de la conciencia antes de interpretaciones previas."},
  {q:"La ÉTICA DEL CUIDADO (Carol Gilligan, Nel Noddings) enfatiza:",o:["La justicia abstracta e imparcial","Las relaciones concretas, la responsabilidad hacia los específicos y el cuidado contextual","Las normas universales","La competencia individual"],a:1,tip:"Gilligan criticó que la ética tradicional (Kohlberg) ignoraba el cuidado, las relaciones y la responsabilidad contextual. Complementa la justicia."},
  {q:"El concepto de AMOR en ÁGAPE (tradición cristiana) y PHILIA (griega) difieren porque:",o:["Son iguales","Ágape: amor incondicional, universal; Philia: amistad y afecto entre iguales","Philia es superior","Ágape solo es religioso"],a:1,tip:"Griegos distinguen: Eros (amor romántico), Philia (amistad), Storge (amor familiar), Ágape (amor incondicional y universal)."},
  {q:"¿Qué enseña el TAOÍSMO sobre el WU WEI?",o:["Actuar con violencia cuando sea necesario","Actuar en armonía con el flujo natural de las cosas, sin forzar ni resistir artificialmente","No hacer absolutamente nada","Solo meditar sin actuar"],a:1,tip:"Wu wei = 'no-acción forzada'. El agua no lucha, pero erosiona la roca. Actuar con la naturaleza, no contra ella."},
  {q:"¿Cuál es la diferencia entre DEBER y VIRTUD como fundamentos éticos?",o:["Son lo mismo","Ética del deber (Kant): cumplir la norma. Ética de la virtud (Aristóteles): desarrollar el carácter excelente","Solo el deber importa en la práctica","La virtud no es aplicable"],a:1,tip:"Kant: '¿Cuál es mi deber?' Aristóteles: '¿Qué tipo de persona debo ser?' Ambas perspectivas son complementarias."},
  {q:"La tradición ZEN enseña principalmente a través de:",o:["Textos largos y complejos","Koans (paradojas irresolubles por la lógica), prácticas de meditación y experiencia directa","Solo ceremonias religiosas","Debates filosóficos formales"],a:1,tip:"El Zen busca la iluminación (satori) más allá de la mente conceptual. Los koans ('¿Qué es el sonido de un solo aplauso?') trascienden la lógica."},
  {q:"¿Qué es la TRASCENDENCIA según la filosofía existencialista?",o:["Morir y ir al cielo","La capacidad humana de ir más allá de lo dado, proyectarse hacia el futuro y crear su propio ser","No existir","La inmortalidad del alma"],a:1,tip:"Sartre: el ser humano no es lo que es, sino lo que se hace. La trascendencia es la libertad de proyectarse hacia lo que aún no somos."},
  {q:"El EUDEMONISMO aristotélico propone que la felicidad:",o:["Es el placer máximo","Es la actividad del alma según la virtud, el florecimiento pleno de las capacidades humanas","Es solo la ausencia de dolor","Depende de la suerte exclusivamente"],a:1,tip:"Eudaimonia ≠ hedone (placer). La felicidad profunda es el florecimiento del ser humano actuando virtuosamente según su naturaleza racional."},
  {q:"¿Qué es el UTILITARISMO (Bentham, Mill)?",o:["Actuar por deber independientemente de las consecuencias","Maximizar la felicidad o bienestar del mayor número posible de personas","Actuar según la tradición","Privilegiar los derechos individuales siempre"],a:1,tip:"Utilitarismo: 'Lo mejor es lo que produce mayor felicidad para el mayor número'. Mill añadió la distinción entre placeres superiores e inferiores."},
  {q:"La INTERSUBJETIVIDAD en filosofía significa:",o:["Que solo existe la realidad subjetiva","Que la realidad y el significado se construyen entre sujetos a través del lenguaje y la experiencia compartida","Que los sujetos están totalmente aislados","Que la objetividad es imposible"],a:1,tip:"Habermas: el entendimiento surge del diálogo entre sujetos. La verdad no es solo subjetiva ni solo objetiva, sino intersubjetiva."},
  {q:"¿Cuál es el aporte de HANNAH ARENDT al pensamiento ético-político?",o:["Promovió el totalitarismo","Analizó el mal banal: el mal no requiere monstruos, sino personas que no piensan ni cuestionan","Defendió el individualismo extremo","Propuso que la violencia es necesaria"],a:1,tip:"Arendt (La banalidad del mal): Eichmann no era monstruo sino un burócrata que no pensaba. Pensar críticamente es responsabilidad ética."},
  {q:"¿Qué es la PRAXIS según Marx y la tradición crítica?",o:["Solo la teoría","La unidad dialéctica entre teoría y acción transformadora de la realidad","Solo la acción sin reflexión","Una forma de meditación"],a:1,tip:"Praxis: teoría + práctica reflexiva orientada a transformar el mundo. No solo interpretar la realidad sino cambiarla conscientemente."},
  {q:"La ALTERIDAD en la filosofía de Lévinas propone:",o:["Que el Otro no importa","Que el rostro del Otro nos interpela ética e infinitamente: el Otro es infinitamente más que nuestra comprensión de él","Que solo importa el yo","Que todos somos iguales en todo"],a:1,tip:"Lévinas: la ética nace ante el rostro del Otro que dice 'no me mates'. La responsabilidad por el Otro es anterior a cualquier filosofía."},
  {q:"¿Cuál es la crítica del EXISTENCIALISMO de Sartre a la 'mala fe'?",o:["Que las personas son siempre auténticas","Que muchas personas huyen de su libertad, actuando como si no pudieran elegir, para evitar la responsabilidad","Que no existe la libertad","Que la autenticidad es imposible"],a:1,tip:"Mala fe (Sartre): fingir que somos lo que somos sin posibilidad de cambio. Ej: 'Soy así, no puedo hacer nada.' La libertad asusta, pero es inevitable."},
  {q:"¿Qué es el CONTRATO SOCIAL (Rousseau, Hobbes, Locke)?",o:["Un documento físico firmado","La idea de que la sociedad y el Estado se fundan en un acuerdo (implícito) entre individuos para vivir juntos","Solo una metáfora literaria","Una forma de gobierno específica"],a:1,tip:"Para Hobbes (miedo), Locke (derechos) y Rousseau (voluntad general): la sociedad surge de un acuerdo entre personas para beneficio mutuo."},
  {q:"¿Cuál es la diferencia entre DEONTOLOGÍA y TELEOLOGÍA en ética?",o:["Son lo mismo","Deontología: lo que importa es la norma o deber; teleología: lo que importa es el fin u objetivo alcanzado","Teleología es siempre correcta","La deontología solo aplica en la religión"],a:1,tip:"Deontología (Kant): el acto es moral si sigue la norma correcta, independientemente del resultado. Teleología (Aristóteles, Mill): el acto es moral según sus consecuencias o fines."},
  {q:"El pensamiento de PAULO FREIRE propone que la educación:",o:["Debe llenar mentes vacías con conocimiento","Debe ser dialógica: educador y educando aprenden juntos, la educación libera la conciencia oprimida","Debe solo obedecer al sistema","Es solo transmisión de información"],a:1,tip:"Freire (Pedagogía del oprimido): la 'educación bancaria' deposita conocimiento pasivo. La educación liberadora dialoga y transforma conciencias."},
  {q:"¿Qué es el PENSAMIENTO COMPLEJO según Edgar Morin?",o:["Solo sistemas complicados","Una forma de pensar que integra, no separa: reconoce la incertidumbre, la contradicción y la interconexión de todo","La filosofía de la complejidad matemática","Solo para científicos"],a:1,tip:"Morin: el pensamiento simplificante separa y reduce. El pensamiento complejo integra, contextualiza y reconoce que todo está interconectado."},
  {q:"La BIOÉTICA como disciplina surge principalmente para:",o:["Estudiar la biología","Reflexionar éticamente sobre dilemas generados por las ciencias de la vida: genética, medicina, ecología","Reemplazar la medicina","Solo regular los hospitales"],a:1,tip:"Bioética: fecundación in vitro, eutanasia, edición genética (CRISPR), medio ambiente... Los avances científicos crean dilemas éticos urgentes."},
  {q:"¿Qué es la FILOSOFÍA DE LA LIBERACIÓN latinoamericana (Dussel, Zea)?",o:["Una corriente que imita la filosofía europea","Un pensamiento que parte de la realidad de los excluidos y oprimidos de América Latina para construir categorías propias","Solo un movimiento político","Una forma de utilitarismo"],a:1,tip:"La filosofía de la liberación (Dussel, años 70) parte del 'no-ser', el excluido, para crear pensamiento filosófico propio desde América Latina."},
  {q:"¿Cuál es el aporte de MARTHA NUSSBAUM al pensamiento ético?",o:["Promovió el estoicismo puro","Desarrolló el enfoque de capacidades: la justicia debe garantizar a todos las capacidades necesarias para florecer humanamente","Defendió el relativismo moral absoluto","Propuso que las emociones no tienen valor moral"],a:1,tip:"Nussbaum (con Sen): las capacidades básicas (educación, salud, emociones, afiliación política) son lo que la justicia debe garantizar a todos."},
{q:"¿Cuál es el imperativo categórico de Kant?",o:["Actuar por placer","Actuar solo según normas que pudiéramos querer que fueran universales","Seguir a la multitud","Actuar según el resultado"],a:1,tip:"Kant: 'Actúa solo según la máxima que puedas querer que sea ley universal.' La forma, no el resultado, determina la moralidad."}
]

};

