  if (k.includes('news') || k.includes('inform') || k.includes('text') || k.includes('wash') || k.includes('audience') || k.includes('research') || k.includes('outline') || k.includes('fox') || k.includes('fable') || k.includes('fabula') || k.includes('moraleja') || k.includes('house') || k.includes('zoo') || k.includes('egg') || k.includes('price') || k.includes('rewrite') || k.includes('turn') || k.includes('cat') || k.includes('synonym') || k.includes('white') || k.includes('instruct') || k.includes('afiche') || k.includes('descript') || k.includes('conector')) return V.default_lang;
