  inteligencia_emocional:[
  // MISIÓN 1 — Neurociencia de las emociones
  {q:"¿Qué parte del cerebro procesa primero las emociones intensas como el miedo?",o:["El córtex prefrontal","La amígdala","El cerebelo","El hipocampo"],a:1,tip:"La amígdala actúa como 'alarma emocional'. Procesa el miedo antes que el pensamiento racional."},
  {q:"El CÓRTEX PREFRONTAL nos ayuda a:",o:["correr más rápido","pensar racionalmente y controlar impulsos","sentir emociones básicas","recordar el pasado"],a:1,tip:"El córtex prefrontal es la sede del pensamiento crítico y el control de impulsos."},
  {q:"¿Qué es el 'secuestro amigdalar'?",o:["cuando la amígdala ayuda a pensar mejor","cuando las emociones intensas bloquean el pensamiento racional","cuando dormimos profundamente","cuando memorizamos algo"],a:1,tip:"El 'secuestro amigdalar' ocurre cuando la emoción desborda la razón. Técnicas de respiración ayudan a recuperar el control."},
  {q:"Los NEUROTRANSMISORES como la dopamina y la serotonina influyen en:",o:["solo en la memoria","el estado de ánimo y las emociones","solo en los movimientos","solo en el sueño"],a:1,tip:"Dopamina: placer y recompensa. Serotonina: bienestar. Su balance afecta cómo nos sentimos."},
  {q:"¿Por qué los adolescentes experimentan emociones más intensas?",o:["porque son irresponsables","porque el córtex prefrontal aún está en desarrollo hasta los 25 años","porque no les importa nada","porque duermen poco"],a:1,tip:"El cerebro adolescente tiene la amígdala muy activa y el córtex prefrontal aún madurando."},
  // MISIÓN 2 — Empatía avanzada y relaciones
  {q:"La EMPATÍA COGNITIVA se diferencia de la EMPATÍA AFECTIVA en que:",o:["son exactamente iguales","cognitiva = entender el punto de vista; afectiva = sentir lo que el otro siente","cognitiva = sentir; afectiva = pensar","ninguna es real"],a:1,tip:"Empatía cognitiva (entender) + afectiva (sentir) = empatía completa."},
  {q:"¿Qué es la FATIGA DE COMPASIÓN?",o:["estar muy cansado de correr","el agotamiento emocional de quienes ayudan constantemente a otros","no querer a nadie","sentir compasión por primera vez"],a:1,tip:"Quienes ayudan mucho (médicos, maestros) pueden experimentar fatiga de compasión. Por eso el autocuidado es esencial."},
  {q:"Una RELACIÓN TÓXICA se caracteriza por:",o:["mucho respeto y apoyo mutuo","control, manipulación o daño emocional repetido","compartir muchas actividades","ser muy buenos amigos"],a:1,tip:"Las relaciones sanas tienen respeto, confianza y apoyo. Las tóxicas generan daño emocional."},
  {q:"¿Qué significa 'poner límites' en una relación?",o:["alejarse de todos","comunicar qué comportamientos no estás dispuesto a tolerar","ser egoísta","no tener amigos"],a:1,tip:"Los límites sanos protegen el bienestar propio y son parte de toda relación saludable."},
  {q:"La ESCUCHA EMPÁTICA profunda implica:",o:["esperar tu turno para hablar","comprender el mensaje emocional detrás de las palabras, sin juzgar","dar consejos siempre","interrumpir para ayudar"],a:1,tip:"Escucha profunda = atender el sentimiento, no solo las palabras; sin juzgar ni interrumpir."},
  // MISIÓN 3 — Resolución de conflictos avanzada
  {q:"¿Cuáles son los 4 pasos del modelo 'DESC' para la comunicación asertiva?",o:["Describir, Expresar, Solicitar, Consecuencias","Discutir, Evaluar, Señalar, Callar","Decidir, Empujar, Seguir, Cambiar","Describir, Enojarse, Señalar, Criticar"],a:0,tip:"DESC: Describir la situación, Expresar sentimientos, Solicitar cambio, indicar Consecuencias positivas."},
  {q:"En mediación escolar, el papel del MEDIADOR es:",o:["decidir quién tiene razón","facilitar la comunicación sin tomar partido","imponer soluciones","castigar a las partes"],a:1,tip:"El mediador es neutral: no juzga ni decide, solo facilita el diálogo."},
  {q:"¿Qué es el 'PENSAMIENTO WIN-WIN' (ganar-ganar) de Stephen Covey?",o:["buscar que yo gane y el otro pierda","buscar acuerdos donde ambas partes obtengan algo valioso","que nadie gane","que el más fuerte decide"],a:1,tip:"Win-Win es una mentalidad de abundancia: hay suficiente para todos si colaboramos."},
  {q:"La VIOLENCIA PASIVA o pasivo-agresiva se expresa como:",o:["gritos y golpes","silencio hostil, sarcasmo o boicot indirecto","comunicación directa","ayuda al otro"],a:1,tip:"La agresividad pasiva daña sin confrontación directa. Es importante reconocerla y comunicarse asertivamente."},
  {q:"¿Por qué el PERDÓN beneficia principalmente a quien perdona?",o:["no beneficia a nadie","libera de la carga emocional del resentimiento, mejorando el bienestar propio","solo beneficia al perdonado","es una señal de debilidad"],a:1,tip:"El perdón no justifica el daño, pero libera al que perdona del peso del resentimiento."},
  // MISIÓN 4 — Liderazgo emocional y bienestar
  {q:"Daniel Goleman identificó como componentes de la IE: autoconciencia, autorregulación, motivación, empatía y:",o:["inteligencia matemática","habilidades sociales","memoria perfecta","fuerza física"],a:1,tip:"Los 5 componentes de la IE según Goleman incluyen las habilidades sociales como el 5to pilar."},
  {q:"Un LÍDER EMOCIONALMENTE INTELIGENTE principalmente:",o:["impone sus decisiones","inspira con empatía, escucha y motiva a su equipo","ignora los sentimientos del grupo","trabaja solo siempre"],a:1,tip:"El liderazgo emocional reconoce las emociones del equipo y las usa para motivar y cohesionar."},
  {q:"¿Qué es el FLUJO o 'flow' según Mihaly Csikszentmihalyi?",o:["estar aburrido","estado de concentración total y satisfacción en una actividad","tener miedo constante","no pensar en nada"],a:1,tip:"El 'flow' es el estado de máximo rendimiento y satisfacción cuando el reto iguala la habilidad."},
  {q:"La REGULACIÓN EMOCIONAL madura implica:",o:["suprimir todas las emociones","sentir, reconocer y expresar emociones de forma adaptativa según el contexto","nunca mostrar emociones","reaccionar siempre impulsivamente"],a:1,tip:"Regulación madura = sentir + nombrar + elegir cómo expresar, según el contexto."},
  {q:"¿Por qué el AUTOCUIDADO emocional NO es egoísmo?",o:["sí es egoísmo","porque necesitamos estar bien para poder ayudar a otros genuinamente","porque nadie necesita ayuda","porque las emociones no importan"],a:1,tip:"Como en el avión: primero tu mascarilla, luego ayudas. No puedes dar lo que no tienes."},
  // MODO EXTRA
  {q:"¿Cuál es la relación entre MINDFULNESS e inteligencia emocional?",o:["no tienen relación","el mindfulness entrena la autoconciencia, base de la IE","el mindfulness elimina las emociones","son conceptos opuestos"],a:1,tip:"Mindfulness desarrolla la autoconciencia, primer pilar de la IE según Goleman."},
  {q:"Las EMOCIONES MORALES como la culpa o el orgullo se diferencian de las primarias porque:",o:["son más simples","implican evaluación moral de las propias acciones","no existen","son iguales a las primarias"],a:1,tip:"Las emociones morales (culpa, vergüenza, orgullo) surgen de comparar acciones con valores propios."},
  {q:"¿Qué es la ALFABETIZACIÓN EMOCIONAL?",o:["aprender a leer mejor","la capacidad de identificar, entender y expresar emociones con vocabulario apropiado","no sentir emociones","ignorar las emociones"],a:1,tip:"Tener vocabulario emocional rico permite identificar y comunicar mejor lo que sentimos."},
  {q:"Un ambiente emocionalmente SEGURO en el aula significa:",o:["que no pasa nada emocionante","que todos pueden expresar emociones sin miedo al juicio o ridiculización","que no hay conflictos","que todos son iguales"],a:1,tip:"La seguridad emocional permite el aprendizaje: sin miedo al error, el cerebro aprende mejor."},
  {q:"Según la neurociencia, ¿qué práctica fortalece las conexiones cerebrales relacionadas con la regulación emocional?",o:["ver televisión muchas horas","la meditación y la reflexión consciente practicadas regularmente","el videojuego","no dormir"],a:1,tip:"La meditación y reflexión consciente fortalecen el córtex prefrontal, clave en la regulación emocional."}
]

