// ═══════════════════════════════════════════
//   TALLER DE ARITMÉTICA — Basado en el taller del Gimnasio Contemporáneo
//   Fracciones, Decimales, Lectura en inglés, Valor Posicional
// ═══════════════════════════════════════════
const QD_TALLER = {
  taller_aritmetica:[
  // MISIÓN 1 — Fracciones a Decimales
  {q:"¿Cuánto es 19/100 en decimal?",o:["1.9","0.19","19.0","0.019"],a:1,tip:"19/100 = 0.19. Divide el numerador entre el denominador: 19 ÷ 100 = 0.19"},
  {q:"¿Cuánto es 8/1000 en decimal?",o:["0.8","8.0","0.008","0.08"],a:2,tip:"8/1000 = 0.008. Ceros hasta completar 3 decimales: 0.008"},
  {q:"¿Cuánto es 5/10 en decimal?",o:["5.0","0.05","0.5","50.0"],a:2,tip:"5/10 = 0.5. Un decimal: 5 ÷ 10 = 0.5"},
  {q:"¿Cuánto es 218/1000 en decimal?",o:["2.18","21.8","0.218","218.0"],a:2,tip:"218/1000 = 0.218. Tres cifras decimales."},
  {q:"¿Cuánto es 17/10 en decimal?",o:["0.17","1.7","17.0","170.0"],a:1,tip:"17/10 = 1.7. Una cifra decimal: 1 entero y 7 décimas."},
  // MISIÓN 2 — Decimales a Fracciones
  {q:"¿Cómo se escribe 0.75 como fracción?",o:["7/5","75/10","75/100","750/100"],a:2,tip:"0.75 = 75/100. El 5 está en las centésimas, así que el denominador es 100."},
  {q:"¿Cómo se escribe 0.008 como fracción?",o:["8/10","8/100","8/1000","80/100"],a:2,tip:"0.008: el 8 está en los milésimos → 8/1000."},
  {q:"¿Cómo se escribe 1.5 como fracción?",o:["15/10","15/100","1/5","5/1"],a:0,tip:"1.5 = 15/10. Un número mixto: 1 entero más 5 décimas = 15 décimas."},
  {q:"¿Cómo se escribe 0.904 como fracción?",o:["94/100","904/1000","9/4","904/100"],a:1,tip:"0.904: el último dígito está en milésimos → 904/1000."},
  {q:"¿Cómo se escribe 10.05 como fracción?",o:["105/10","1005/100","10/5","1050/100"],a:1,tip:"10.05 = 1005/100. Dos decimales → denominador 100."},
  // MISIÓN 3 — Leer Decimales en Inglés
  {q:"18.24 en inglés es:",o:["eighteen point twenty-four","eighteen and twenty-four hundredths","eighteen point two four","eighteen hundredths"],a:1,tip:"Decimales en inglés: parte entera AND + décimas en palabras + lugar. 18.24 = eighteen AND twenty-four hundredths."},
  {q:"'Fifty-eight and four thousandths' en número es:",o:["58.4","58.04","58.004","580.4"],a:2,tip:"Thousandths = milésimas → 3 decimales. Fifty-eight = 58. Four thousandths = 0.004 → 58.004"},
  {q:"1,245.6 en inglés es:",o:["one thousand two hundred forty-five point six","one thousand two hundred forty-five and six tenths","twelve forty-five and six","one thousand two forty-five"],a:1,tip:"Decimales en inglés: AND separa la parte entera de la decimal. Six tenths = 6 décimas."},
  {q:"'Three and sixty-three hundredths' en número es:",o:["363.0","3.063","3.63","36.3"],a:2,tip:"Hundredths = centésimas → 2 decimales. Three = 3. Sixty-three hundredths = 0.63 → 3.63"},
  {q:"58.004 en inglés es:",o:["fifty-eight and four hundredths","fifty-eight point zero four","fifty-eight and four thousandths","fifty-eight and four tenths"],a:2,tip:"0.004 está en los milésimos (thousandths). Por eso: fifty-eight and four thousandths."},
  // MISIÓN 4 — Valor Posicional
  {q:"En el número 14,275.983, ¿en qué posición está el dígito 8?",o:["décimas","centésimas","milésimas","unidades"],a:1,tip:"14,275.983 → .983: el 9 en décimas, el 8 en centésimas, el 3 en milésimas."},
  {q:"En 76.403, ¿cuál es el valor del dígito 3?",o:["3","0.3","0.03","0.003"],a:3,tip:"76.403 → .403: 4 décimas, 0 centésimas, 3 milésimas. Valor = 0.003"},
  {q:"¿Cuál es el decimal de 89/10000?",o:["0.8900","0.00089","0.000089","0.0089"],a:3,tip:"89/10000 = 0.0089. Cuatro cifras decimales: 0.0089"},
  {q:"En el número 14,275.983, ¿cuál es el valor del dígito 5?",o:["5000","500","5","0.5"],a:2,tip:"En 14,275.983 el 5 está en la posición de las UNIDADES. Su valor es 5."},
  {q:"'Three hundred five and sixty-nine thousandths' en número es:",o:["35.69","305.69","35.069","305.069"],a:3,tip:"305 = three hundred five. 0.069 = sixty-nine thousandths (3 decimales). → 305.069"},
  // MODO EXTRA — Desafío mixto
  {q:"En el número 54.98, ¿cuál es el dígito en el lugar de las decenas?",o:["5","4","9","8"],a:0,tip:"54.98: el 5 está en las DECENAS, el 4 en las unidades, el 9 en décimas, el 8 en centésimas."},
  {q:"0.0234 como fracción es:",o:["234/100","234/1000","234/10000","2340/100"],a:2,tip:"0.0234: el último dígito (4) está en diezmilésimas → 234/10000."},
  {q:"¿Cuál de estos números tiene el mayor valor?",o:["0.9","0.09","0.009","0.99"],a:3,tip:"0.99 es el mayor: tiene 9 décimas y 9 centésimas. Compara siempre posición por posición."},
  {q:"344.0012 como fracción es:",o:["3440012/1000","3440012/10000","34400120/100000","3440012/100"],a:1,tip:"0.0012: el 2 está en las diezmilésimas → denominador 10000. 344.0012 = 3440012/10000."},
  {q:"¿Cuáles son las partes de un número decimal?",o:["numerador y denominador","parte entera y numerador","parte entera y parte decimal","denominador y parte decimal"],a:2,tip:"Todo número decimal tiene una PARTE ENTERA (antes del punto) y una PARTE DECIMAL (después del punto)."}
]}; 


// ═══════════════════════════════════════════
//   TRAINING_QS — Pool de preguntas mixtas
//   para el Mundo de Entrenamiento
// ═══════════════════════════════════════════
const TRAINING_QS = (function() {
  const pool = [];
  const subjects = ['ingles','lenguaje','matematicas','ciencias','sociales'];
  // Toma las primeras 6 preguntas de cada mundo básico (30 en total)
  subjects.forEach(s => {
    if (QD[s]) pool.push(...QD[s].slice(0, 6));
  });
  // Add a few taller questions too
  if (typeof QD_TALLER !== 'undefined' && QD_TALLER.taller_aritmetica) {
    pool.push(...QD_TALLER.taller_aritmetica.slice(0, 5));
  }
  return pool;
})();
